"use client";

import React, { useEffect, useState } from 'react';
import { AnnualPerformanceMatrix } from '@/components/research/AnnualPerformanceMatrix';
import { researchService, AnnualReturn } from '@/services/researchService';

export default function AnnualReturnsView() {
    const [data, setData] = useState<AnnualReturn[]>([]);
    const [loading, setLoading] = useState(true);
    const [schemeCode, setSchemeCode] = useState(101);
    const [error, setError] = useState<string | null>(null);
    useEffect(() => {
        const fetchData = async () => {
            try {
                setLoading(true);
                const result = await researchService.getAnnualReturns(schemeCode);
                setData(result);
            } catch (error) {
                console.error("Failed to fetch annual returns", error);
                const msg = err.response?.data?.message || "An unexpected error occurred. Please verify dates and try again.";
                setError(msg);
            } finally {
                setLoading(false);
            }
        };
        fetchData();
    }, [schemeCode]);

    if (loading) return <div>Loading...</div>;

    return (
        <div className="space-y-4">
            <div className="p-4 bg-muted/20 rounded-lg">
                <p className="text-sm text-muted-foreground mb-2">Select Scheme (Demo)</p>
                <select
                    className="p-2 border rounded"
                    value={schemeCode}
                    onChange={(e) => setSchemeCode(Number(e.target.value))}
                >
                    <option value={101}>Scheme 101</option>
                    <option value={102}>Scheme 102</option>
                </select>
            </div>
            <AnnualPerformanceMatrix data={data} />
        </div>
    );
}

"use client";

import React, { useEffect, useState } from 'react';
import {
    LineChart, ArrowUpDown, Info, Activity
} from 'lucide-react';
import {
    Card, CardContent, CardHeader, CardTitle
} from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import {
    Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";
import {
    Tooltip, TooltipContent, TooltipProvider, TooltipTrigger
} from "@/components/ui/tooltip";
import { researchService, BenchmarkMonitorResponse } from '@/services/researchService';
import { Loader2 } from 'lucide-react';
import { ErrorAlert } from '@/components/ui/ErrorAlert';

export default function BenchmarkMonitorView() {
    const [data, setData] = useState<BenchmarkMonitorResponse[]>([]);
    const [loading, setLoading] = useState(true);
    const [sortConfig, setSortConfig] = useState<{ key: string; direction: 'asc' | 'desc' }>({ key: 'return1Y', direction: 'desc' });
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        const fetch = async () => {
            try {
                const res = await researchService.getBenchmarkMonitor();
                setData(res);
            } catch (err) {
                console.error(err);
                const msg = err.response?.data?.message || "An unexpected error occurred. Please verify dates and try again.";
                setError(msg);

            } finally {
                setLoading(false);
            }
        };
        fetch();
    }, []);

    const sortedData = React.useMemo(() => {
        if (!data) return [];
        return [...data].sort((a: any, b: any) => {
            if (a[sortConfig.key] < b[sortConfig.key]) return sortConfig.direction === 'asc' ? -1 : 1;
            if (a[sortConfig.key] > b[sortConfig.key]) return sortConfig.direction === 'asc' ? 1 : -1;
            return 0;
        });
    }, [data, sortConfig]);

    const handleSort = (key: string) => {
        setSortConfig(current => ({
            key,
            direction: current.key === key && current.direction === 'desc' ? 'asc' : 'desc',
        }));
    };

    const getCellClass = (val: number | null | undefined) => {
        if (val === null || val === undefined) return "text-muted-foreground";
        if (val >= 15) return "bg-emerald-100 text-emerald-800 dark:bg-emerald-900/40 dark:text-emerald-300 font-bold";
        if (val >= 0) return "text-emerald-600 dark:text-emerald-400 font-medium";
        if (val < 0) return "bg-red-50 text-red-600 dark:bg-red-900/20 dark:text-red-400";
        return "text-foreground";
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-700 pb-20">
            <div>
                <h1 className="text-2xl font-bold tracking-tight flex items-center gap-2">
                    <Activity className="w-6 h-6 text-emerald-500" />
                    Benchmark Monitor
                </h1>
                <p className="text-sm text-muted-foreground mt-1">
                    Track the performance of major market indices and benchmarks.
                </p>
            </div>

            <ErrorAlert message={error} />

            <Card className="border-border/50 shadow-md">
                <CardHeader className="pb-2 bg-muted/10 border-b border-border/50">
                    <div className="flex items-center justify-between">
                        <CardTitle className="text-sm font-medium uppercase">Market Indices Matrix</CardTitle>
                        <Badge variant="outline" className="bg-background">
                            {data.length} Indices
                        </Badge>
                    </div>
                </CardHeader>
                <CardContent className="p-0">
                    <div className="overflow-x-auto">
                        <Table>
                            <TableHeader>
                                <TableRow className="hover:bg-transparent">
                                    <TableHead className="w-[300px] sticky left-0 bg-background z-20 shadow-[1px_0_0_0_rgba(0,0,0,0.1)]">Benchmark</TableHead>
                                    <SortableHead label="1 Year" sortKey="return1Y" activeSort={sortConfig} onSort={handleSort} />
                                    <SortableHead label="3 Year" sortKey="return3Y" activeSort={sortConfig} onSort={handleSort} />
                                    <SortableHead label="5 Year" sortKey="return5Y" activeSort={sortConfig} onSort={handleSort} />
                                    <SortableHead label="Since Inc." sortKey="returnInception" activeSort={sortConfig} onSort={handleSort} />

                                    <TableHead className="text-center w-[100px]">
                                        <div className="flex items-center justify-center gap-1">
                                            Vol.
                                            <TooltipProvider>
                                                <Tooltip>
                                                    <TooltipTrigger><Info className="w-3 h-3 text-muted-foreground" /></TooltipTrigger>
                                                    <TooltipContent>Standard Deviation (Volatility)</TooltipContent>
                                                </Tooltip>
                                            </TooltipProvider>
                                        </div>
                                    </TableHead>
                                    <TableHead className="text-center w-[100px]">Sharpe</TableHead>
                                </TableRow>
                            </TableHeader>
                            <TableBody>
                                {loading ? (
                                    <TableRow>
                                        <TableCell colSpan={7} className="h-48 text-center">
                                            <Loader2 className="w-8 h-8 animate-spin mx-auto text-emerald-500 mb-2" />
                                            <p className="text-muted-foreground">Loading indices...</p>
                                        </TableCell>
                                    </TableRow>
                                ) : (
                                    sortedData.map((b) => (
                                        <TableRow key={b.benchmarkName} className="group">
                                            <TableCell className="font-medium sticky left-0 bg-background z-10 group-hover:bg-muted/50 shadow-[1px_0_0_0_rgba(0,0,0,0.1)]">
                                                {b.benchmarkName}
                                                {b.nseSymbol && (
                                                    <div className="text-[10px] text-muted-foreground font-mono mt-0.5">
                                                        {b.nseSymbol}
                                                    </div>
                                                )}
                                            </TableCell>
                                            <DataCell val={b.return1Y} getStyle={getCellClass} />
                                            <DataCell val={b.return3Y} getStyle={getCellClass} />
                                            <DataCell val={b.return5Y} getStyle={getCellClass} />
                                            <DataCell val={b.returnInception} getStyle={getCellClass} />

                                            <TableCell className="text-center font-mono text-sm text-muted-foreground border-l border-border/30">
                                                {b.stdDev !== null ? b.stdDev.toFixed(2) : '-'}
                                            </TableCell>
                                            <TableCell className="text-center font-mono text-sm text-muted-foreground border-l border-border/30">
                                                {b.sharpeRatio !== null ? b.sharpeRatio.toFixed(2) : '-'}
                                            </TableCell>
                                        </TableRow>
                                    ))
                                )}
                            </TableBody>
                        </Table>
                    </div>
                </CardContent>
            </Card>
        </div>
    );
}

const SortableHead = ({ label, sortKey, activeSort, onSort }: any) => (
    <TableHead
        className="text-right cursor-pointer hover:bg-muted/50 transition-colors w-[110px]"
        onClick={() => onSort(sortKey)}
    >
        <div className="flex items-center justify-end gap-1">
            {label}
            <ArrowUpDown className={`w-3 h-3 ${activeSort.key === sortKey ? 'text-emerald-500 opacity-100' : 'opacity-20'}`} />
        </div>
    </TableHead>
);

const DataCell = ({ val, getStyle }: any) => (
    <TableCell className={`text-right font-mono text-sm border-l border-border/30 ${getStyle(val)}`}>
        {(val !== null && val !== undefined) ? `${val.toFixed(2)}%` : '-'}
    </TableCell>
);

"use client";

import React, { useEffect, useState } from 'react';
import {
    LayoutDashboard, ArrowUpDown, Info, TrendingUp, AlertTriangle
} from 'lucide-react';
import {
    Card, CardContent, CardHeader, CardTitle, CardDescription
} from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import {
    Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";
import {
    Tooltip, TooltipContent, TooltipProvider, TooltipTrigger
} from "@/components/ui/tooltip";
import { researchService, CategoryMonitorResponse } from '@/services/researchService';
import { Loader2 } from 'lucide-react';

export default function CategoryMonitorView() {
    const [data, setData] = useState<CategoryMonitorResponse[]>([]);
    const [loading, setLoading] = useState(true);
    const [sortConfig, setSortConfig] = useState<{ key: string; direction: 'asc' | 'desc' }>({ key: 'avgReturn3Y', direction: 'desc' });

    useEffect(() => {
        const fetch = async () => {
            try {
                const res = await researchService.getCategoryMonitor();
                setData(res);
            } finally {
                setLoading(false);
            }
        };
        fetch();
    }, []);

    // Sorting Logic
    const sortedData = React.useMemo(() => {
        if (!data) return [];
        return [...data].sort((a: any, b: any) => {
            if (a[sortConfig.key] < b[sortConfig.key]) return sortConfig.direction === 'asc' ? -1 : 1;
            if (a[sortConfig.key] > b[sortConfig.key]) return sortConfig.direction === 'asc' ? 1 : -1;
            return 0;
        });
    }, [data, sortConfig]);

    const handleSort = (key: string) => {
        setSortConfig(current => ({
            key,
            direction: current.key === key && current.direction === 'desc' ? 'asc' : 'desc',
        }));
    };

    // Heatmap Color Logic
    const getCellClass = (val: number | null | undefined) => {
        if (val === null || val === undefined) return "text-muted-foreground";
        if (val >= 20) return "bg-emerald-100 text-emerald-800 dark:bg-emerald-900/40 dark:text-emerald-300 font-bold";
        if (val >= 10) return "text-emerald-600 dark:text-emerald-400 font-medium";
        if (val < 0) return "bg-red-50 text-red-600 dark:bg-red-900/20 dark:text-red-400";
        return "text-foreground";
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-700 pb-20">
            <div>
                <h1 className="text-2xl font-bold tracking-tight flex items-center gap-2">
                    <LayoutDashboard className="w-6 h-6 text-emerald-500" />
                    Mutual Fund Category Monitor
                </h1>
                <p className="text-sm text-muted-foreground mt-1">
                    Bird&#39;s-eye view of how different sectors and categories are performing.
                </p>
            </div>

            <Card className="border-border/50 shadow-md">
                <CardHeader className="pb-2 bg-muted/10 border-b border-border/50">
                    <div className="flex items-center justify-between">
                        <CardTitle className="text-sm font-medium uppercase">Category Performance Matrix</CardTitle>
                        <Badge variant="outline" className="bg-background">
                            {data.length} Categories Tracked
                        </Badge>
                    </div>
                </CardHeader>
                <CardContent className="p-0">
                    <div className="overflow-x-auto">
                        <Table>
                            <TableHeader>
                                <TableRow className="hover:bg-transparent">
                                    <TableHead className="w-[250px] sticky left-0 bg-background z-20 shadow-[1px_0_0_0_rgba(0,0,0,0.1)]">Category Name</TableHead>
                                    <SortableHead label="1M" sortKey="avgReturn1M" activeSort={sortConfig} onSort={handleSort} />
                                    <SortableHead label="3M" sortKey="avgReturn3M" activeSort={sortConfig} onSort={handleSort} />
                                    <SortableHead label="6M" sortKey="avgReturn6M" activeSort={sortConfig} onSort={handleSort} />
                                    <SortableHead label="1Y" sortKey="avgReturn1Y" activeSort={sortConfig} onSort={handleSort} />
                                    <SortableHead label="3Y" sortKey="avgReturn3Y" activeSort={sortConfig} onSort={handleSort} />
                                    <SortableHead label="5Y" sortKey="avgReturn5Y" activeSort={sortConfig} onSort={handleSort} />
                                    <TableHead className="text-center w-[100px]">
                                        <div className="flex items-center justify-center gap-1">
                                            Vol.
                                            <TooltipProvider>
                                                <Tooltip>
                                                    <TooltipTrigger><Info className="w-3 h-3 text-muted-foreground" /></TooltipTrigger>
                                                    <TooltipContent>Avg Standard Deviation (Risk)</TooltipContent>
                                                </Tooltip>
                                            </TooltipProvider>
                                        </div>
                                    </TableHead>
                                </TableRow>
                            </TableHeader>
                            <TableBody>
                                {loading ? (
                                    <TableRow>
                                        <TableCell colSpan={9} className="h-48 text-center">
                                            <Loader2 className="w-8 h-8 animate-spin mx-auto text-emerald-500 mb-2" />
                                            <p className="text-muted-foreground">Aggregating market data...</p>
                                        </TableCell>
                                    </TableRow>
                                ) : (
                                    sortedData.map((cat) => (
                                        <TableRow key={cat.categoryName} className="group">
                                            <TableCell className="font-medium sticky left-0 bg-background z-10 group-hover:bg-muted/50 shadow-[1px_0_0_0_rgba(0,0,0,0.1)]">
                                                {cat.categoryName}
                                                <div className="text-[10px] text-muted-foreground font-normal">
                                                    {cat.schemeCount} Schemes
                                                </div>
                                            </TableCell>
                                            <DataCell val={cat.avgReturn1M} getStyle={getCellClass} />
                                            <DataCell val={cat.avgReturn3M} getStyle={getCellClass} />
                                            <DataCell val={cat.avgReturn6M} getStyle={getCellClass} />
                                            <DataCell val={cat.avgReturn1Y} getStyle={getCellClass} />
                                            <DataCell val={cat.avgReturn3Y} getStyle={getCellClass} bold />
                                            <DataCell val={cat.avgReturn5Y} getStyle={getCellClass} />
                                            <TableCell className="text-center font-mono text-xs text-muted-foreground">
                                                {cat.avgStdDev !== undefined && cat.avgStdDev !== null
                                                    ? cat.avgStdDev.toFixed(2)
                                                    : '-'}
                                            </TableCell>
                                        </TableRow>
                                    ))
                                )}
                            </TableBody>
                        </Table>
                    </div>
                </CardContent>
            </Card>
        </div>
    );
}

// Sub-components
const SortableHead = ({ label, sortKey, activeSort, onSort }: any) => (
    <TableHead
        className="text-right cursor-pointer hover:bg-muted/50 transition-colors w-[100px]"
        onClick={() => onSort(sortKey)}
    >
        <div className="flex items-center justify-end gap-1">
            {label}
            <ArrowUpDown className={`w-3 h-3 ${activeSort.key === sortKey ? 'text-emerald-500 opacity-100' : 'opacity-20'}`} />
        </div>
    </TableHead>
);

// FIX APPLIED HERE: Added check for undefined
const DataCell = ({ val, getStyle, bold }: any) => (
    <TableCell className={`text-right font-mono text-sm border-l border-border/30 ${getStyle(val)} ${bold ? 'bg-muted/20' : ''}`}>
        {(val !== null && val !== undefined) ? `${val.toFixed(2)}%` : '-'}
    </TableCell>
);

"use client";

import React, { useEffect, useState } from 'react';
import {
    Scale, Landmark, TrendingUp, ArrowRight, Percent, Search, Check, AlertCircle
} from 'lucide-react';
import {
    Card, CardContent, CardHeader, CardTitle, CardDescription
} from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import {
    Select, SelectContent, SelectItem, SelectTrigger, SelectValue
} from '@/components/ui/select';
import {
    Popover, PopoverContent, PopoverTrigger,
} from "@/components/ui/popover";
import {
    Command, CommandInput, CommandEmpty, CommandGroup, CommandItem,
} from "@/components/ui/command";
import { researchService, FdVsDebtResponse, SchemeDropdownDto } from '@/services/researchService';
import { cn } from "@/lib/utils";
import { Loader2 } from 'lucide-react';

import { ErrorAlert } from '@/components/ui/ErrorAlert';

export default function FdVsDebtView() {
    // --- State ---
    const [categories, setCategories] = useState<string[]>([]);
    const [category, setCategory] = useState("");
    const [schemes, setSchemes] = useState<SchemeDropdownDto[]>([]);

    // Inputs
    const [amount, setAmount] = useState(100000);
    const [fdRate, setFdRate] = useState(7.0);
    const [taxRate, setTaxRate] = useState(30);
    const [startDate, setStartDate] = useState("2023-01-01");
    const [endDate, setEndDate] = useState(new Date().toISOString().split('T')[0]);
    const [selectedScheme, setSelectedScheme] = useState<SchemeDropdownDto | null>(null);

    // Data
    const [data, setData] = useState<FdVsDebtResponse | null>(null);
    const [loading, setLoading] = useState(false);
    const [comboOpen, setComboOpen] = useState(false);

    // Initial Load
    useEffect(() => {
        researchService.getCategories().then(cats => {
            setCategories(cats);
            // Default to a Debt category if available
            const debtCat = cats.find(c => c.toLowerCase().includes("debt")) || cats[0];
            if(debtCat) setCategory(debtCat);
        });
    }, []);

    // Load Schemes
    useEffect(() => {
        if (!category) return;
        researchService.getSchemesByCategory(category).then(setSchemes);
    }, [category]);

    const handleCalculate = async () => {
        if (!selectedScheme) return;
        setLoading(true);
        setError(null); // Reset error
        try {
            const res = await researchService.compareFdVsDebt({
                investmentAmount: amount,
                fdInterestRate: fdRate,
                debtSchemeCode: selectedScheme.schemeCode,
                startDate,
                endDate,
                taxRate
            });
            setData(res);
        } catch (err) {
            console.error(err);
            const msg = err.response?.data?.message || "An unexpected error occurred. Please verify dates and try again.";
            setError(msg);
        } finally {
            setLoading(false);
        }
    };

    const [error, setError] = useState<string | null>(null);

    const fmt = (val: number) => new Intl.NumberFormat('en-IN', {
        style: 'currency', currency: 'INR', maximumFractionDigits: 0
    }).format(val);

    return (
        <div className="space-y-8 animate-in fade-in duration-700 pb-20">
            {/* Header */}
            <div>
                <h1 className="text-2xl font-bold tracking-tight flex items-center gap-2">
                    <Scale className="w-6 h-6 text-emerald-500" />
                    Debt Funds vs Fixed Deposit
                </h1>
                <p className="text-sm text-muted-foreground mt-1">
                    Compare post-tax returns of Debt Mutual Funds against traditional Fixed Deposits.
                </p>
            </div>

            {/* Input Card */}
            <Card className="border-border/50 shadow-md bg-card">
                <CardHeader className="bg-muted/10 pb-4 border-b border-border/50">
                    <CardTitle className="text-base text-blue-600 dark:text-blue-400">Comparison Parameters</CardTitle>
                </CardHeader>
                <CardContent className="p-6 space-y-6">

                    {/* Top Row: FD vs Debt Config */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">

                        {/* 1. FD Configuration */}
                        <div className="space-y-4 p-4 rounded-xl bg-orange-50/50 dark:bg-orange-950/10 border border-orange-100 dark:border-orange-900/30">
                            <div className="flex items-center gap-2 mb-2">
                                <Landmark className="w-4 h-4 text-orange-600" />
                                <h3 className="text-sm font-bold text-orange-700 dark:text-orange-400">Fixed Deposit</h3>
                            </div>

                            <div className="space-y-2">
                                <label className="text-xs font-semibold text-muted-foreground uppercase">Deposit Amount</label>
                                <div className="relative">
                                    <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">₹</span>
                                    <Input
                                        type="number"
                                        value={amount}
                                        onChange={(e) => setAmount(Number(e.target.value))}
                                        className="pl-7 bg-background"
                                    />
                                </div>
                            </div>
                            <div className="space-y-2">
                                <label className="text-xs font-semibold text-muted-foreground uppercase">Interest Rate (%)</label>
                                <Input
                                    type="number"
                                    value={fdRate}
                                    onChange={(e) => setFdRate(Number(e.target.value))}
                                    className="bg-background"
                                />
                            </div>
                        </div>

                        {/* 2. Debt Fund Configuration */}
                        <div className="space-y-4 p-4 rounded-xl bg-emerald-50/50 dark:bg-emerald-950/10 border border-emerald-100 dark:border-emerald-900/30">
                            <div className="flex items-center gap-2 mb-2">
                                <TrendingUp className="w-4 h-4 text-emerald-600" />
                                <h3 className="text-sm font-bold text-emerald-700 dark:text-emerald-400">Debt Mutual Fund</h3>
                            </div>

                            <div className="space-y-2">
                                <label className="text-xs font-semibold text-muted-foreground uppercase">Category</label>
                                <Select value={category} onValueChange={setCategory}>
                                    <SelectTrigger className="bg-background h-10 w-full">
                                        {/* TRUNCATION FIX: Wraps text to prevent layout breaking */}
                                        <span className="truncate text-left block w-full pr-2">
                                            <SelectValue />
                                        </span>
                                    </SelectTrigger>
                                    <SelectContent>
                                        {categories.map(c => <SelectItem key={c} value={c}>{c}</SelectItem>)}
                                    </SelectContent>
                                </Select>
                            </div>

                            <div className="space-y-2">
                                <label className="text-xs font-semibold text-muted-foreground uppercase">Scheme</label>
                                <Popover open={comboOpen} onOpenChange={setComboOpen}>
                                    <PopoverTrigger asChild>
                                        <Button variant="outline" role="combobox" className="w-full justify-between bg-background text-muted-foreground font-normal h-10 px-3">
                                            <span className="truncate">{selectedScheme ? selectedScheme.schemeName : "Select Fund..."}</span>
                                            <Search className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                                        </Button>
                                    </PopoverTrigger>
                                    <PopoverContent className="w-[300px] p-0" align="start">
                                        <Command>
                                            <CommandInput placeholder="Search debt fund..." />
                                            <CommandEmpty>No fund found.</CommandEmpty>
                                            <CommandGroup className="max-h-[250px] overflow-auto">
                                                {schemes.map((s) => (
                                                    <CommandItem
                                                        key={s.schemeCode}
                                                        value={s.schemeName}
                                                        onSelect={() => {
                                                            setSelectedScheme(s);
                                                            setComboOpen(false);
                                                        }}
                                                    >
                                                        <Check className={cn("mr-2 h-4 w-4", selectedScheme?.schemeCode === s.schemeCode ? "opacity-100" : "opacity-0")} />
                                                        <span className="truncate">{s.schemeName}</span>
                                                    </CommandItem>
                                                ))}
                                            </CommandGroup>
                                        </Command>
                                    </PopoverContent>
                                </Popover>
                            </div>
                        </div>
                    </div>

                    {/* Common Params: Dates & Tax */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6 pt-2">
                        <div className="space-y-2">
                            <label className="text-xs font-semibold text-muted-foreground uppercase">Start Date</label>
                            <Input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} />
                        </div>
                        <div className="space-y-2">
                            <label className="text-xs font-semibold text-muted-foreground uppercase">End Date</label>
                            <Input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} />
                        </div>
                        <div className="space-y-2">
                            <label className="text-xs font-semibold text-muted-foreground uppercase">Tax Slab (%)</label>
                            <Select value={taxRate.toString()} onValueChange={(v) => setTaxRate(Number(v))}>
                                <SelectTrigger><SelectValue /></SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="0">0% (No Tax)</SelectItem>
                                    <SelectItem value="10">10%</SelectItem>
                                    <SelectItem value="20">20%</SelectItem>
                                    <SelectItem value="30">30%</SelectItem>
                                    <SelectItem value="39">39% (Highest)</SelectItem>
                                </SelectContent>
                            </Select>
                        </div>
                    </div>

                    <Button onClick={handleCalculate} disabled={loading || !selectedScheme} className="w-full md:w-auto bg-emerald-600 hover:bg-emerald-700 text-white font-bold shadow-md">
                        {loading ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : "Compare Returns"}
                    </Button>

                </CardContent>
            </Card>

            <ErrorAlert message={error} />

            {/* Results */}
            {data && (
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

                    {/* Comparison Summary */}
                    <Card className="lg:col-span-3 border-border/50 shadow-sm bg-gradient-to-br from-background to-muted/20">
                        <CardHeader className="text-center pb-2">
                            <CardTitle className="text-xl">Analysis Summary</CardTitle>
                            <CardDescription>
                                {data.debtWins
                                    ? <span className="text-emerald-600 font-bold flex items-center justify-center gap-1"><TrendingUp className="w-4 h-4"/> Debt Fund Wins by {fmt(data.wealthDifference)}</span>
                                    : <span className="text-orange-600 font-bold flex items-center justify-center gap-1"><Landmark className="w-4 h-4"/> Fixed Deposit Wins by {fmt(Math.abs(data.wealthDifference))}</span>}
                            </CardDescription>
                        </CardHeader>
                    </Card>

                    {/* Left: FD Result */}
                    <ResultCard
                        title="Fixed Deposit"
                        icon={Landmark}
                        colorClass="text-orange-600"
                        bgClass="bg-orange-50 dark:bg-orange-950/10"
                        data={{
                            maturity: data.fdMaturityValue,
                            profit: data.fdPreTaxProfit,
                            tax: data.fdTaxLiability,
                            postTax: data.fdPostTaxValue,
                            xirr: data.fdPostTaxReturnPercent
                        }}
                    />

                    {/* Right: Debt Result */}
                    <ResultCard
                        title="Debt Mutual Fund"
                        subTitle={data.schemeName}
                        icon={TrendingUp}
                        colorClass="text-emerald-600"
                        bgClass="bg-emerald-50 dark:bg-emerald-950/10"
                        isWinner={data.debtWins}
                        data={{
                            maturity: data.debtMaturityValue,
                            profit: data.debtPreTaxProfit,
                            tax: data.debtTaxLiability,
                            postTax: data.debtPostTaxValue,
                            xirr: data.debtPostTaxReturnPercent
                        }}
                    />

                    {/* Tax Impact Breakdown Table (Full Width) */}
                    <Card className="lg:col-span-3 border-border/50">
                        <CardHeader className="bg-muted/10 py-3 border-b border-border/50">
                            <CardTitle className="text-sm font-bold uppercase">Taxation Impact Breakdown</CardTitle>
                        </CardHeader>
                        <div className="p-0 overflow-x-auto">
                            <table className="w-full text-sm text-left">
                                <thead className="bg-muted/30 text-muted-foreground font-medium">
                                <tr>
                                    <th className="px-6 py-3">Metric</th>
                                    <th className="px-6 py-3 text-right">Fixed Deposit</th>
                                    <th className="px-6 py-3 text-right text-emerald-700 dark:text-emerald-400">Debt Fund</th>
                                </tr>
                                </thead>
                                <tbody className="divide-y divide-border/40">
                                <tr className="hover:bg-muted/10">
                                    <td className="px-6 py-3 font-medium text-muted-foreground">Pre-Tax Profit</td>
                                    <td className="px-6 py-3 text-right font-mono">{fmt(data.fdPreTaxProfit)}</td>
                                    <td className="px-6 py-3 text-right font-mono font-bold">{fmt(data.debtPreTaxProfit)}</td>
                                </tr>
                                <tr className="hover:bg-muted/10">
                                    <td className="px-6 py-3 font-medium text-muted-foreground">Tax Payable ({taxRate}%)</td>
                                    <td className="px-6 py-3 text-right text-red-500 font-mono">-{fmt(data.fdTaxLiability)}</td>
                                    <td className="px-6 py-3 text-right text-red-500 font-mono">-{fmt(data.debtTaxLiability)}</td>
                                </tr>
                                <tr className="bg-muted/5 font-bold">
                                    <td className="px-6 py-3 text-foreground">Net Post-Tax Profit</td>
                                    <td className="px-6 py-3 text-right text-orange-600">{fmt(data.fdPostTaxValue - amount)}</td>
                                    <td className="px-6 py-3 text-right text-emerald-600">{fmt(data.debtPostTaxValue - amount)}</td>
                                </tr>
                                </tbody>
                            </table>
                        </div>
                    </Card>
                </div>
            )}
        </div>
    );
}

// Helper Component for Result Cards
function ResultCard({ title, subTitle, icon: Icon, colorClass, bgClass, data, isWinner }: any) {
    const fmt = (val: number) => new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(val);

    return (
        <Card className={`lg:col-span-1.5 border-border/50 shadow-sm relative overflow-hidden ${isWinner ? 'ring-2 ring-emerald-500/50' : ''}`}>
            {isWinner && <div className="absolute top-0 right-0 bg-emerald-500 text-white text-[10px] px-2 py-0.5 rounded-bl-lg font-bold uppercase">Winner</div>}
            <CardHeader className={`${bgClass} border-b border-border/10 pb-4`}>
                <div className="flex items-start gap-3">
                    <div className={`p-2 rounded-lg bg-white/80 dark:bg-black/20 ${colorClass}`}>
                        <Icon className="w-5 h-5" />
                    </div>
                    <div>
                        <CardTitle className={`text-base ${colorClass}`}>{title}</CardTitle>
                        {subTitle && <CardDescription className="line-clamp-1 text-xs mt-0.5" title={subTitle}>{subTitle}</CardDescription>}
                    </div>
                </div>
            </CardHeader>
            <CardContent className="p-5 space-y-4">
                <div className="flex justify-between items-center border-b border-border/40 pb-3">
                    <span className="text-sm text-muted-foreground">Maturity Value</span>
                    <span className="text-lg font-bold text-foreground">{fmt(data.maturity)}</span>
                </div>
                <div className="flex justify-between items-center">
                    <span className="text-xs uppercase font-semibold text-muted-foreground">Net Post-Tax Return</span>
                    <Badge variant="outline" className={`${colorClass} bg-transparent border-current`}>
                        {data.xirr.toFixed(2)}%
                    </Badge>
                </div>
                <div className="pt-2">
                    <div className="flex justify-between text-xs text-muted-foreground mb-1">
                        <span>Post-Tax Value</span>
                    </div>
                    <div className={`text-2xl font-black ${colorClass}`}>
                        {fmt(data.postTax)}
                    </div>
                </div>
            </CardContent>
        </Card>
    );


}

"use client";

import React, { useEffect, useState } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import {
    Plus, X, Info, Loader2
} from 'lucide-react';
import {
    Card, CardContent, CardHeader, CardTitle, CardDescription
} from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import {
    Dialog, DialogContent, DialogTrigger,
} from "@/components/ui/dialog";
import {
    BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell
} from 'recharts';
import { researchService, FundCompareResponse, FundRowDto } from '@/services/researchService';
import { ErrorAlert } from '@/components/ui/ErrorAlert';

export default function FundCompareView() {
    const router = useRouter();
    const searchParams = useSearchParams();

    // Data State
    const [selectedIds, setSelectedIds] = useState<number[]>([]);
    const [data, setData] = useState<FundCompareResponse | null>(null);
    const [loading, setLoading] = useState(false);

    // UI State
    const [isSelectorOpen, setIsSelectorOpen] = useState(false);

    // STATE RETENTION FIX: Keep the category state in the Parent
    const [lastCategory, setLastCategory] = useState<string>("");

    const [error, setError] = useState<string | null>(null);
    // 1. Sync State with URL
    useEffect(() => {
        const schemesParam = searchParams.get('schemes');
        if (schemesParam) {
            const ids = schemesParam.split(',').map(Number).filter(n => !isNaN(n));
            setSelectedIds(ids);
        }
    }, [searchParams]);

    // 2. Fetch Comparison Data
    useEffect(() => {
        if (selectedIds.length === 0) {
            setData(null);
            return;
        }
        const fetchData = async () => {
            setLoading(true);
            try {
                const res = await researchService.getFundComparison({ schemeCodes: selectedIds });
                setData(res);

                // Optional: If we have data and no category is selected yet,
                // set it to the first fund's category to be helpful.
                // But we respect the user's manual selection if 'lastCategory' is already set.
                if (!lastCategory && res.funds.length > 0) {
                    setLastCategory(res.funds[0].category);
                }
            } catch (err) {
                console.error("Comparison fetch failed", err);
                const msg = err.response?.data?.message || "An unexpected error occurred. Please verify dates and try again.";
                setError(msg);
            } finally {
                setLoading(false);
            }
        };
        fetchData();
    }, [selectedIds]); // Removed 'lastCategory' from dependency to avoid loops

    // 3. Handlers
    const addScheme = (id: number) => {
        if (selectedIds.includes(id)) return;
        if (selectedIds.length >= 5) {
            alert("You can compare up to 5 funds.");
            return;
        }
        const newIds = [...selectedIds, id];
        updateUrl(newIds);
        setIsSelectorOpen(false);
    };

    const removeScheme = (id: number) => {
        const newIds = selectedIds.filter(x => x !== id);
        updateUrl(newIds);
    };

    const updateUrl = (ids: number[]) => {
        const params = new URLSearchParams();
        if (ids.length > 0) params.set('schemes', ids.join(','));
        router.push(`?${params.toString()}`);
        setSelectedIds(ids);
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-700 pb-20">
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
                <div>
                    <h1 className="text-2xl md:text-3xl font-bold tracking-tight text-foreground flex items-center gap-2">
                        Fund Comparison
                    </h1>
                    <p className="text-sm text-muted-foreground mt-1">
                        Compare up to 5 mutual funds side-by-side.
                    </p>
                </div>

                <div className="flex items-center gap-2">
                    <Dialog open={isSelectorOpen} onOpenChange={setIsSelectorOpen}>
                        <DialogTrigger asChild>
                            <Button className="bg-emerald-600 hover:bg-emerald-700 text-white gap-2 shadow-md hover:shadow-lg transition-all">
                                <Plus className="w-4 h-4" /> Add Fund
                            </Button>
                        </DialogTrigger>
                        {/* We keep the content mounted or pass state to ensure retention.
                           Here we pass 'lastCategory' and 'setLastCategory'
                        */}
                        <DialogContent className="max-w-4xl h-[80vh] flex flex-col p-0 overflow-hidden bg-background">
                            <FundSelector
                                onSelect={addScheme}
                                currentlySelected={selectedIds}
                                activeCategory={lastCategory}
                                onCategoryChange={setLastCategory}
                            />
                        </DialogContent>
                    </Dialog>
                </div>
            </div>

            {/* Active Filters */}
            {data?.funds && data.funds.length > 0 && (
                <div className="flex flex-col sm:flex-row sm:items-center gap-2 sm:gap-4 bg-muted/30 p-3 rounded-xl border border-border/50">

                    {/* Label: Full width on mobile, auto on desktop */}
                    <span className="text-xs font-semibold text-muted-foreground uppercase tracking-wider shrink-0">
                        COMPARING ({data.funds.length}/5):
                    </span>

                    {/* Badges Container: Wraps nicely below label on mobile */}
                    <div className="flex flex-wrap gap-2 items-center">
                        {data.funds.map(f => (
                            <Badge
                                key={f.schemeCode}
                                variant="secondary"
                                className="pl-2 pr-1 py-1 gap-2 bg-background border border-border hover:bg-background h-7"
                            >
                    <span className="truncate max-w-[150px] sm:max-w-[200px]">
                        {f.schemeName}
                    </span>
                                <button
                                    onClick={() => removeScheme(f.schemeCode)}
                                    className="hover:bg-red-100 hover:text-red-600 rounded-full p-0.5 transition-colors"
                                >
                                    <X className="w-3 h-3" />
                                </button>
                            </Badge>
                        ))}

                        {data.funds.length < 5 && (
                            <Button
                                variant="ghost"
                                size="sm"
                                className="text-[11px] font-medium text-muted-foreground h-7 border border-dashed border-border hover:border-emerald-500 hover:text-emerald-600 px-2"
                                onClick={() => setIsSelectorOpen(true)}
                            >
                                <Plus className="w-3 h-3 mr-1" /> Add
                            </Button>
                        )}
                    </div>
                </div>
            )}
            <ErrorAlert message={error} />
            {/* Main Content */}
            {loading ? (
                <div className="h-64 flex flex-col items-center justify-center gap-4 text-muted-foreground">
                    <Loader2 className="w-10 h-10 animate-spin text-emerald-500" />
                    <p>Fetching comparison data...</p>
                </div>
            ) : !data || data.funds.length === 0 ? (
                <EmptyState onAdd={() => setIsSelectorOpen(true)} />
            ) : (
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    {/* Left: Table */}
                    <Card className="lg:col-span-2 border-border/50 shadow-sm overflow-hidden">
                        <CardHeader className="pb-4 border-b border-border/50 bg-muted/10">
                            <CardTitle className="text-lg">Performance Metrics</CardTitle>
                            <CardDescription>Data as of {data.dataAsOn}</CardDescription>
                        </CardHeader>
                        <div className="overflow-x-auto">
                            <table className="w-full text-sm text-left">
                                <thead className="bg-muted/30 text-muted-foreground font-medium">
                                <tr>
                                    <th className="px-4 py-3 min-w-[180px]">Metric</th>
                                    {data.funds.map(f => (
                                        <th key={f.schemeCode} className="px-4 py-3 min-w-[140px] font-semibold text-foreground">
                                            <div className="line-clamp-2" title={f.schemeName}>{f.schemeName}</div>
                                        </th>
                                    ))}
                                </tr>
                                </thead>
                                <tbody className="divide-y divide-border/40">
                                <tr className="bg-muted/5"><td className="px-4 py-2 font-medium text-muted-foreground text-xs uppercase tracking-wider" colSpan={data.funds.length + 1}>Basic Info</td></tr>
                                <DataRow label="Category" funds={data.funds} field="category" />
                                <DataRow label="Benchmark" funds={data.funds} field="benchmarkName" />
                                <DataRow label="Fund House" funds={data.funds} field="fundHouse" />

                                <tr className="bg-muted/5"><td className="px-4 py-2 font-medium text-muted-foreground text-xs uppercase tracking-wider" colSpan={data.funds.length + 1}>Returns (%)</td></tr>
                                <DataRow label="1 Year" funds={data.funds} field="return1y" isReturn />
                                <DataRow label="3 Year" funds={data.funds} field="return3y" isReturn highlight />
                                <DataRow label="5 Year" funds={data.funds} field="return5y" isReturn />
                                <DataRow label="Inception" funds={data.funds} field="returnInception" isReturn />

                                <tr className="bg-muted/5"><td className="px-4 py-2 font-medium text-muted-foreground text-xs uppercase tracking-wider" colSpan={data.funds.length + 1}>Risk Ratios</td></tr>
                                <DataRow label="Vol. (StdDev)" funds={data.funds} field="stdDev" formatter={(v: number) => v?.toFixed(2)} />
                                <DataRow label="Alpha (3Y)" funds={data.funds} field="alpha3y" formatter={(v: number) => v?.toFixed(2)} />
                                <DataRow label="Beta (3Y)" funds={data.funds} field="beta3y" formatter={(v: number) => v?.toFixed(2)} />
                                <DataRow label="Sharpe Ratio" funds={data.funds} field="sharpeRatio" formatter={(v: number) => v?.toFixed(2)} />
                                </tbody>
                            </table>
                        </div>
                    </Card>

                    {/* Right: Charts */}
                    <div className="space-y-6">
                        <Card className="border-border/50 shadow-sm">
                            <CardHeader>
                                <CardTitle className="text-sm font-medium uppercase tracking-wide">3Y Return Comparison</CardTitle>
                            </CardHeader>
                            <CardContent className="h-[300px]">
                                <ResponsiveContainer width="100%" height="100%">
                                    <BarChart data={data.funds} layout="vertical" margin={{ left: 0, right: 30 }}>
                                        <CartesianGrid strokeDasharray="3 3" horizontal={false} opacity={0.2} />
                                        <XAxis type="number" hide />
                                        <YAxis dataKey="schemeName" type="category" width={100} tick={{fontSize: 10}} hide />
                                        <Tooltip
                                            cursor={{fill: 'transparent'}}
                                            content={({ active, payload }) => {
                                                if (active && payload && payload.length) {
                                                    const d = payload[0].payload;
                                                    return (
                                                        <div className="bg-popover border border-border p-2 rounded shadow-lg text-xs">
                                                            <p className="font-bold mb-1">{d.schemeName}</p>
                                                            <p className="text-emerald-500 font-mono">{d.return3y?.toFixed(2)}%</p>
                                                        </div>
                                                    )
                                                }
                                                return null;
                                            }}
                                        />
                                        <Bar dataKey="return3y" radius={[0, 4, 4, 0]} barSize={30}>
                                            {data.funds.map((entry, index) => (
                                                <Cell key={`cell-${index}`} fill={['#10b981', '#3b82f6', '#f59e0b', '#8b5cf6', '#ec4899'][index % 5]} />
                                            ))}
                                        </Bar>
                                    </BarChart>
                                </ResponsiveContainer>
                            </CardContent>
                        </Card>

                        <Card className="bg-blue-50/50 dark:bg-blue-900/10 border-blue-100 dark:border-blue-900/30">
                            <CardContent className="p-4 flex gap-3">
                                <Info className="w-5 h-5 text-blue-600 shrink-0 mt-0.5" />
                                <div className="text-sm text-blue-800 dark:text-blue-300">
                                    <p className="font-semibold mb-1">Comparison Tip</p>
                                    Compare Alpha (Skill) vs Beta (Risk). Higher Alpha with lower Beta indicates a fund manager generating returns with better risk management.
                                </div>
                            </CardContent>
                        </Card>
                    </div>
                </div>
            )}
        </div>
    );
}

// --- Sub-Components ---

function EmptyState({ onAdd }: { onAdd: () => void }) {
    return (
        <Card className="border-dashed border-2 border-border/60 bg-muted/10 h-64 flex flex-col items-center justify-center text-center p-6">
            <h3 className="text-lg font-semibold mb-1">No Funds Selected</h3>
            <p className="text-sm text-muted-foreground max-w-sm mb-4">
                Select funds to analyze their performance side-by-side.
            </p>
            <Button onClick={onAdd} variant="outline" className="gap-2">
                <Plus className="w-4 h-4" /> Select Funds
            </Button>
        </Card>
    );
}

function DataRow({ label, funds, field, isReturn, highlight, formatter }: any) {
    return (
        <tr className={highlight ? "bg-emerald-50/50 dark:bg-emerald-900/10" : "hover:bg-muted/20"}>
            <td className="px-4 py-3 font-medium text-muted-foreground">{label}</td>
            {funds.map((f: any) => {
                const val = f[field];
                return (
                    <td key={f.schemeCode} className="px-4 py-3">
                        {isReturn ? (
                            <span className={`font-mono font-medium ${val >= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-red-500'}`}>
                                {val !== null ? `${val.toFixed(2)}%` : '-'}
                            </span>
                        ) : (
                            <span className="text-foreground">
                                {formatter ? formatter(val) : val || '-'}
                            </span>
                        )}
                    </td>
                );
            })}
        </tr>
    );
}

// --- UPDATED FUND SELECTOR ---
import { DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Search, Check } from 'lucide-react';

interface FundSelectorProps {
    onSelect: (id: number) => void;
    currentlySelected: number[];
    activeCategory: string; // Controlled by parent
    onCategoryChange: (c: string) => void; // Update parent
}

function FundSelector({ onSelect, currentlySelected, activeCategory, onCategoryChange }: FundSelectorProps) {
    const [categories, setCategories] = useState<string[]>([]);
    const [loading, setLoading] = useState(false);
    const [funds, setFunds] = useState<FundRowDto[]>([]);
    const [page, setPage] = useState(0);
    const [totalPages, setTotalPages] = useState(0);

    // 1. Initial Load of Categories
    useEffect(() => {
        researchService.getCategories().then(cats => {
            setCategories(cats);

            // Only set default if parent hasn't set one yet
            if (!activeCategory && cats.length > 0) {
                const defaultCat = cats.includes("Equity") ? "Equity" : cats[0];
                onCategoryChange(defaultCat);
            }
        });
    }, []); // Run once on mount

    // 2. Fetch Funds when Category (from props) or Page changes
    useEffect(() => {
        if (!activeCategory) return;
        const fetch = async () => {
            setLoading(true);
            try {
                const res = await researchService.getTopPerformingFunds({
                    category: activeCategory,
                    page,
                    size: 10,
                    sortBy: 'return_3y',
                    sortDirection: 'DESC'
                });
                setFunds(res.funds);
                setTotalPages(res.totalPages);
            } catch (err) {
                console.error(err);
                const msg = err.response?.data?.message || "An unexpected error occurred. Please verify dates and try again.";
                setError(msg);
            } finally {
                setLoading(false);
            }
        };
        fetch();
    }, [activeCategory, page]);

    // Handle Category Switch
    const handleCategoryChange = (val: string) => {
        onCategoryChange(val); // Update parent state
        setPage(0); // Reset local pagination
    };

    return (
        <div className="flex flex-col h-full bg-background">
            <DialogHeader className="px-6 py-4 border-b border-border flex-none">
                <DialogTitle>Select Fund to Compare</DialogTitle>
            </DialogHeader>

            {/* Filter Bar */}
            <div className="p-4 border-b border-border bg-muted/10 flex flex-col sm:flex-row gap-4 flex-none items-center">

                {/* Category Select - Fixed Truncation */}
                <div className="w-full sm:w-[250px] min-w-0">
                    <Select value={activeCategory} onValueChange={handleCategoryChange}>
                        <SelectTrigger className="bg-background border-input/60 shadow-sm w-full">
                            {/* TRUNCATION FIX:
                    The span + truncate ensures text doesn't overflow on mobile
                */}
                            <span className="truncate text-left block w-full pr-2">
                    <SelectValue placeholder="Select Category" />
                </span>
                        </SelectTrigger>
                        <SelectContent>
                            {categories.map(c => <SelectItem key={c} value={c}>{c}</SelectItem>)}
                        </SelectContent>
                    </Select>
                </div>

                {/* Search Input - Improved Alignment */}
                {/*<div className="flex-1 w-full relative">
                    <div className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground pointer-events-none">
                        <Search className="w-4 h-4" />
                    </div>
                    <input
                        type="text"
                        placeholder="Search funds..."
                        disabled
                        className="w-full h-10 pl-9 pr-4 rounded-md border border-input/60 bg-background text-sm text-muted-foreground placeholder:text-muted-foreground/50 opacity-60 cursor-not-allowed shadow-sm focus:outline-none"
                    />
                </div>*/}
            </div>

            {/* List */}
            <div className="flex-1 overflow-auto p-0 relative">
                {loading ? (
                    <div className="absolute inset-0 flex items-center justify-center bg-background/80 backdrop-blur-sm z-10">
                        <Loader2 className="animate-spin text-emerald-500 w-8 h-8" />
                    </div>
                ) : null}

                <table className="w-full text-sm text-left">
                    <thead className="bg-muted sticky top-0 z-10 shadow-sm">
                    <tr>
                        <th className="px-6 py-3 font-semibold text-muted-foreground bg-muted">Scheme Name</th>
                        <th className="px-4 py-3 text-right font-semibold text-muted-foreground bg-muted">3Y Return</th>
                        <th className="px-4 py-3 text-center font-semibold text-muted-foreground bg-muted">Action</th>
                    </tr>
                    </thead>
                    <tbody className="divide-y divide-border/40">
                    {funds.map(f => {
                        const isSelected = currentlySelected.includes(f.schemeCode);
                        return (
                            <tr key={f.schemeCode} className="hover:bg-muted/30 transition-colors">
                                <td className="px-6 py-3 font-medium text-foreground">
                                    {f.schemeName}
                                    <div className="text-[10px] text-muted-foreground mt-0.5 uppercase tracking-wider">{activeCategory}</div>
                                </td>
                                <td className="px-4 py-3 text-right font-mono font-medium text-emerald-600 dark:text-emerald-400">
                                    {f.return3y?.toFixed(2)}%
                                </td>
                                <td className="px-4 py-3 text-center">
                                    <Button
                                        size="sm"
                                        variant={isSelected ? "secondary" : "outline"}
                                        disabled={isSelected}
                                        onClick={() => onSelect(f.schemeCode)}
                                        className={`h-8 w-24 ${isSelected ? '' : 'hover:border-emerald-500 hover:text-emerald-600 hover:bg-emerald-50 dark:hover:bg-emerald-950/20'}`}
                                    >
                                        {isSelected ? <Check className="w-3 h-3 mr-1" /> : <Plus className="w-3 h-3 mr-1" />}
                                        {isSelected ? "Added" : "Add"}
                                    </Button>
                                </td>
                            </tr>
                        );
                    })}
                    </tbody>
                </table>
            </div>

            {/* Pagination Footer */}
            <div className="p-4 border-t border-border flex justify-between items-center bg-muted/10 flex-none">
                <span className="text-xs text-muted-foreground">Page {page + 1} of {totalPages}</span>
                <div className="flex gap-2">
                    <Button variant="outline" size="sm" disabled={page === 0} onClick={() => setPage(p => p - 1)}>Prev</Button>
                    <Button variant="outline" size="sm" disabled={page >= totalPages - 1} onClick={() => setPage(p => p + 1)}>Next</Button>
                </div>
            </div>
        </div>
    );
}

"use client";

import React, { useEffect, useState } from 'react';
import {
    Waves, Plus, X, Search, Check, Loader2, Calendar
} from 'lucide-react';
import {
    Card, CardContent, CardHeader, CardTitle
} from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import {
    Select, SelectContent, SelectItem, SelectTrigger, SelectValue
} from '@/components/ui/select';
import {
    Popover, PopoverContent, PopoverTrigger,
} from "@/components/ui/popover";
import {
    Command, CommandInput, CommandEmpty, CommandGroup, CommandItem,
} from "@/components/ui/command";
import {
    LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend, ReferenceLine
} from 'recharts';
import { researchService, RollingReturnsResponse, SchemeDropdownDto } from '@/services/researchService';
import { cn } from "@/lib/utils";

export default function RollingReturnsView() {
    const [categories, setCategories] = useState<string[]>([]);
    const [category, setCategory] = useState("");
    const [schemes, setSchemes] = useState<SchemeDropdownDto[]>([]);

    // Config
    const [selectedFunds, setSelectedFunds] = useState<SchemeDropdownDto[]>([]);
    const [period, setPeriod] = useState("3Y");
    const [startDate, setStartDate] = useState("2015-01-01"); // Default lookback start

    // Data
    const [data, setData] = useState<RollingReturnsResponse | null>(null);
    const [loading, setLoading] = useState(false);
    const [comboOpen, setComboOpen] = useState(false);

    // Initial Load
    useEffect(() => {
        researchService.getCategories().then(cats => {
            setCategories(cats);
            if(cats.length > 0) setCategory(cats.includes("Equity") ? "Equity" : cats[0]);
        });
    }, []);

    useEffect(() => {
        if (!category) return;
        researchService.getSchemesByCategory(category).then(setSchemes);
    }, [category]);

    const calculate = async () => {
        if (selectedFunds.length === 0) return;
        setLoading(true);
        try {
            const res = await researchService.calculateRollingReturns({
                schemeCodes: selectedFunds.map(f => f.schemeCode),
                period,
                startDate // Optional: send to filter backend graph data
            });
            setData(res);
        } finally {
            setLoading(false);
        }
    };

    // Chart Data Preparation
    const chartData = React.useMemo(() => {
        if (!data || !data.funds.length) return [];
        // Align data based on the first fund
        const base = data.funds[0].dataPoints;
        return base.map((p, idx) => {
            const point: any = { date: p.date };
            data.funds.forEach(fund => {
                const match = fund.dataPoints.find(dp => dp.date === p.date);
                if (match) point[`fund_${fund.schemeCode}`] = match.returnVal;
            });
            return point;
        });
    }, [data]);

    const COLORS = ['#10b981', '#3b82f6', '#f59e0b'];

    return (
        <div className="space-y-6 animate-in fade-in duration-700 pb-20">
            <div>
                <h1 className="text-2xl font-bold tracking-tight flex items-center gap-2">
                    <Waves className="w-6 h-6 text-emerald-500" />
                    Rolling Returns Analysis
                </h1>
                <p className="text-sm text-muted-foreground mt-1">
                    Evaluate fund consistency over every {period} period. The &#34;Gold Standard&#34; of performance analysis.
                </p>
            </div>

            {/* Config Card */}
            <Card className="border-border/50 shadow-md">
                <CardHeader className="bg-muted/10 pb-4 border-b border-border/50">
                    <CardTitle className="text-base">Analysis Configuration</CardTitle>
                </CardHeader>
                <CardContent className="p-6 space-y-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 items-end">

                        {/* 1. Category Selector */}
                        {/* Added min-w-0 to prevent flex item overflow */}
                        <div className="space-y-2 lg:col-span-1 min-w-0">
                            <label className="text-xs font-semibold text-muted-foreground uppercase">Category</label>
                            <Select value={category} onValueChange={setCategory}>
                                <SelectTrigger className="w-full h-10 bg-background border-input/60 shadow-sm">
                                    {/* TRUNCATE FIX: Ensures long category names don't break layout */}
                                    <span className="truncate text-left block w-full pr-2">
                                        <SelectValue placeholder="Select Category" />
                                    </span>
                                </SelectTrigger>
                                <SelectContent>
                                    {categories.map(c => <SelectItem key={c} value={c}>{c}</SelectItem>)}
                                </SelectContent>
                            </Select>
                        </div>

                        {/* 2. Fund Search (Max 3) */}
                        {/* Added min-w-0 and adjusted col-span */}
                        <div className="space-y-2 lg:col-span-2 min-w-0">
                            <label className="text-xs font-semibold text-muted-foreground uppercase">Add Funds (Max 3)</label>
                            <Popover open={comboOpen} onOpenChange={setComboOpen}>
                                <PopoverTrigger asChild>
                                    <Button
                                        variant="outline"
                                        className="w-full justify-between font-normal text-muted-foreground h-10 bg-background border-input/60 shadow-sm px-3"
                                    >
                                        {/* TRUNCATE FIX: Prevents button from expanding beyond grid column */}
                                        <span className="truncate">Select Fund...</span>
                                        <Search className="ml-2 h-4 w-4 opacity-50 shrink-0"/>
                                    </Button>
                                </PopoverTrigger>

                                {/* WIDTH FIX: Matches the trigger button width exactly using CSS var */}
                                <PopoverContent className="w-[var(--radix-popover-trigger-width)] min-w-[300px] p-0" align="start">
                                    <Command>
                                        <CommandInput placeholder="Search funds..." />
                                        <CommandEmpty>No fund found.</CommandEmpty>
                                        <CommandGroup className="max-h-[250px] overflow-auto">
                                            {schemes.map(s => (
                                                <CommandItem key={s.schemeCode} value={s.schemeName} onSelect={() => {
                                                    if (selectedFunds.length < 3 && !selectedFunds.find(f => f.schemeCode === s.schemeCode)) {
                                                        setSelectedFunds([...selectedFunds, s]);
                                                    }
                                                    setComboOpen(false);
                                                }}>
                                                    <Check className={cn("mr-2 h-4 w-4", selectedFunds.find(f => f.schemeCode === s.schemeCode) ? "opacity-100" : "opacity-0")}/>
                                                    <span className="truncate">{s.schemeName}</span>
                                                </CommandItem>
                                            ))}
                                        </CommandGroup>
                                    </Command>
                                </PopoverContent>
                            </Popover>
                        </div>

                        <div className="space-y-2 lg:col-span-1">
                            <label className="text-xs font-semibold text-muted-foreground uppercase">Rolling Period</label>
                            <Select value={period} onValueChange={setPeriod}>
                                <SelectTrigger><SelectValue /></SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="1Y">1 Year</SelectItem>
                                    <SelectItem value="3Y">3 Years</SelectItem>
                                    <SelectItem value="5Y">5 Years</SelectItem>
                                    <SelectItem value="7Y">7 Years</SelectItem>
                                    <SelectItem value="10Y">10 Years</SelectItem>
                                </SelectContent>
                            </Select>
                        </div>
                    </div>

                    {selectedFunds.length > 0 && (
                        <div className="flex flex-wrap gap-2 mt-3">
                            {selectedFunds.map((f, i) => (
                                <Badge
                                    key={f.schemeCode}
                                    variant="secondary"
                                    className="pl-2 pr-1 py-1 h-auto min-h-[28px] border border-border bg-background hover:bg-muted flex items-center max-w-full" >
                                    <div className="w-2 h-2 rounded-full mr-2 shrink-0" style={{ backgroundColor: COLORS[i % COLORS.length] }} />
                                    <span className="truncate text-xs max-w-[180px] sm:max-w-[300px]" title={f.schemeName}>
                                        {f.schemeName}
                                    </span>
                                    <button
                                        onClick={() => setSelectedFunds(selectedFunds.filter(x => x.schemeCode !== f.schemeCode))}
                                        className="ml-2 hover:text-red-500 shrink-0 p-0.5 rounded-full hover:bg-red-50 transition-colors">
                                        <X className="w-3 h-3" />
                                    </button>
                                </Badge>
                            ))}
                        </div>
                    )}

                    <Button onClick={calculate} disabled={loading || selectedFunds.length === 0} className="w-full bg-emerald-600 hover:bg-emerald-700 text-white font-bold">
                        {loading ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Waves className="w-4 h-4 mr-2" />}
                        Run Analysis
                    </Button>
                </CardContent>
            </Card>

            {/* Results */}
            {data && (
                <div className="grid grid-cols-1 gap-6">
                    {/* Graph */}
                    <Card className="border-border/50 shadow-sm">
                        <CardHeader>
                            <CardTitle className="text-sm font-medium uppercase tracking-wide">
                                Rolling Returns History ({period} Period)
                            </CardTitle>
                        </CardHeader>
                        <CardContent className="h-[450px]">
                            <ResponsiveContainer width="100%" height="100%">
                                <LineChart data={chartData} margin={{ top: 20, right: 30, left: 10, bottom: 0 }}>
                                    <CartesianGrid strokeDasharray="3 3" vertical={false} opacity={0.1} />
                                    <XAxis dataKey="date" tick={{fontSize: 12}} minTickGap={50} tickFormatter={(val) => new Date(val).getFullYear().toString()}/>
                                    <YAxis tickFormatter={(val) => `${val}%`} domain={['auto', 'auto']} />
                                    <Tooltip labelFormatter={(v) => new Date(v).toLocaleDateString()} formatter={(val: number) => `${val.toFixed(2)}%`} />
                                    <Legend />
                                    <ReferenceLine y={0} stroke="#94a3b8" strokeDasharray="3 3" />
                                    {data.funds.map((f, i) => (
                                        <Line key={f.schemeCode} type="monotone" dataKey={`fund_${f.schemeCode}`} name={f.schemeName} stroke={COLORS[i]} strokeWidth={2} dot={false} />
                                    ))}
                                </LineChart>
                            </ResponsiveContainer>
                        </CardContent>
                    </Card>

                    {/* Stats Table */}
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {data.funds.map((f, i) => (
                            <Card key={f.schemeCode} className="border-t-4" style={{ borderColor: COLORS[i] }}>
                                <CardHeader className="pb-2">
                                    <CardTitle className="text-sm font-bold truncate" title={f.schemeName}>{f.schemeName}</CardTitle>
                                </CardHeader>
                                <CardContent className="pt-2">
                                    <div className="grid grid-cols-2 gap-y-4 text-sm">
                                        <div>
                                            <p className="text-xs text-muted-foreground uppercase">Average</p>
                                            <p className="text-xl font-bold">{f.stats.average.toFixed(2)}%</p>
                                        </div>
                                        <div>
                                            <p className="text-xs text-muted-foreground uppercase">Max (Best)</p>
                                            <p className="text-xl font-bold text-emerald-600">{f.stats.max.toFixed(2)}%</p>
                                        </div>
                                        <div>
                                            <p className="text-xs text-muted-foreground uppercase">Min (Worst)</p>
                                            <p className="text-xl font-bold text-red-500">{f.stats.min.toFixed(2)}%</p>
                                        </div>
                                        <div>
                                            <p className="text-xs text-muted-foreground uppercase">Negative Periods</p>
                                            <p className="text-xl font-bold text-orange-500">{f.stats.negativePercent.toFixed(1)}%</p>
                                        </div>
                                    </div>
                                </CardContent>
                            </Card>
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
}

"use client";

import React, { useEffect, useState } from 'react';
import {
    Calculator, Plus, X, Calendar, Search, TrendingUp, Check, Loader2
} from 'lucide-react';
import {
    Card, CardContent, CardHeader, CardTitle
} from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from "@/components/ui/input";
import {
    Select, SelectContent, SelectItem, SelectTrigger, SelectValue
} from '@/components/ui/select';
import {
    Popover, PopoverContent, PopoverTrigger,
} from "@/components/ui/popover";
import {
    Command, CommandInput, CommandEmpty, CommandGroup, CommandItem,
} from "@/components/ui/command";
import { Checkbox } from "@/components/ui/checkbox";
import {
    LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend
} from 'recharts';
import { researchService, HistoricalSipResponse, SchemeDropdownDto } from '@/services/researchService';
import { cn } from "@/lib/utils";

export default function SipCalculatorView() {
    // --- State ---
    const [categories, setCategories] = useState<string[]>([]);
    const [category, setCategory] = useState("");
    const [schemes, setSchemes] = useState<SchemeDropdownDto[]>([]);

    // Form State
    const [selectedFunds, setSelectedFunds] = useState<SchemeDropdownDto[]>([]);
    const [amount, setAmount] = useState(5000);
    const [frequency, setFrequency] = useState("Monthly");
    const [startDate, setStartDate] = useState("2020-01-01");
    const [endDate, setEndDate] = useState(new Date().toISOString().split('T')[0]);
    const [isStepUp, setIsStepUp] = useState(false);
    const [stepUpPercent, setStepUpPercent] = useState(10);

    // Results
    const [result, setResult] = useState<HistoricalSipResponse | null>(null);
    const [loading, setLoading] = useState(false);

    // Initial Load
    useEffect(() => {
        researchService.getCategories().then(cats => {
            setCategories(cats);
            if(cats.length > 0) setCategory(cats.includes("Equity") ? "Equity" : cats[0]);
        });
    }, []);

    // Load Schemes on Category Change
    useEffect(() => {
        if (!category) return;
        researchService.getSchemesByCategory(category).then(setSchemes);
    }, [category]);

    // Handlers
    const addFund = (fund: SchemeDropdownDto) => {
        if (selectedFunds.length >= 3) return;
        if (!selectedFunds.find(f => f.schemeCode === fund.schemeCode)) {
            setSelectedFunds([...selectedFunds, fund]);
        }
    };

    const removeFund = (code: number) => {
        setSelectedFunds(selectedFunds.filter(f => f.schemeCode !== code));
    };

    const calculate = async () => {
        if (selectedFunds.length === 0) return;
        setLoading(true);
        try {
            const res = await researchService.calculateHistoricalSip({
                schemeCodes: selectedFunds.map(f => f.schemeCode),
                amount,
                frequency,
                startDate,
                endDate,
                stepUpPercentage: isStepUp ? stepUpPercent : 0
            });
            setResult(res);
        } catch (err) {
            console.error(err);
        } finally {
            setLoading(false);
        }
    };

    // Helper for Combobox
    const [openCombo, setOpenCombo] = useState(false);

    // Chart Data Preparation (Merge multiple lines)
    const chartData = React.useMemo(() => {
        if (!result || !result.results.length) return [];

        // Use the first fund's dates as the x-axis basis
        const baseData = result.results[0].chartData;

        return baseData.map((point, idx) => {
            const row: any = { date: point.date, invested: point.invested };
            // Add value for each fund
            result.results.forEach((res, i) => {
                // Safety check for index
                if (res.chartData[idx]) {
                    row[`fund_${res.schemeCode}`] = res.chartData[idx].value;
                    row[`name_${res.schemeCode}`] = res.schemeName;
                }
            });
            return row;
        });
    }, [result]);

    const COLORS = ['#10b981', '#3b82f6', '#f59e0b'];

    return (
        <div className="space-y-8 animate-in fade-in duration-700 pb-20">
            {/* Header */}
            <div>
                <h1 className="text-2xl font-bold tracking-tight flex items-center gap-2">
                    <TrendingUp className="w-6 h-6 text-emerald-500" />
                    Mutual Fund SIP Calculator
                </h1>
                <p className="text-sm text-muted-foreground mt-1">
                    Backtest your SIP returns with actual historical data.
                </p>
            </div>

            {/* Input Card */}
            <Card className="border-border/50 shadow-md bg-card">
                <CardHeader className="bg-muted/10 pb-4 border-b border-border/50">
                    <CardTitle className="text-base text-blue-600 dark:text-blue-400">Configuration</CardTitle>
                </CardHeader>
                <CardContent className="p-6 space-y-6">

                    {/* Fund Selection Section */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div className="space-y-2">
                            <label className="text-xs font-semibold text-muted-foreground uppercase">Select Category</label>
                            <Select value={category} onValueChange={setCategory}>
                                <SelectTrigger className="bg-background"><SelectValue /></SelectTrigger>
                                <SelectContent>
                                    {categories.map(c => <SelectItem key={c} value={c}>{c}</SelectItem>)}
                                </SelectContent>
                            </Select>
                        </div>

                        <div className="space-y-2">
                            <label className="text-xs font-semibold text-muted-foreground uppercase">Add Funds (Max 3)</label>
                            <Popover open={openCombo} onOpenChange={setOpenCombo}>
                                <PopoverTrigger asChild>
                                    <Button variant="outline" role="combobox" aria-expanded={openCombo} className="w-full justify-between bg-background text-muted-foreground font-normal">
                                        Select Fund to Add...
                                        <Search className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                                    </Button>
                                </PopoverTrigger>
                                <PopoverContent className="w-[400px] p-0" align="start">
                                    <Command>
                                        <CommandInput placeholder="Search fund name..." />
                                        <CommandEmpty>No fund found.</CommandEmpty>
                                        <CommandGroup className="max-h-[250px] overflow-auto">
                                            {schemes.map((s) => (
                                                <CommandItem
                                                    key={s.schemeCode}
                                                    value={s.schemeName}
                                                    onSelect={() => {
                                                        addFund(s);
                                                        setOpenCombo(false);
                                                    }}
                                                >
                                                    <Check className={cn("mr-2 h-4 w-4", selectedFunds.find(f => f.schemeCode === s.schemeCode) ? "opacity-100" : "opacity-0")} />
                                                    {s.schemeName}
                                                </CommandItem>
                                            ))}
                                        </CommandGroup>
                                    </Command>
                                </PopoverContent>
                            </Popover>
                        </div>
                    </div>

                    {/* Selected Funds List */}
                    {selectedFunds.length > 0 && (
                        <div className="flex flex-col gap-2 bg-muted/20 p-3 rounded-lg border border-border/50">
                            {selectedFunds.map((fund, idx) => (
                                <div key={fund.schemeCode} className="flex items-center justify-between bg-background p-2 rounded border border-border shadow-sm">
                                    <div className="flex items-center gap-3">
                                        <span className="flex items-center justify-center w-5 h-5 rounded-full bg-muted text-xs font-bold text-muted-foreground">{idx + 1}</span>
                                        <span className="text-sm font-medium truncate max-w-[250px] sm:max-w-md">{fund.schemeName}</span>
                                    </div>
                                    <button onClick={() => removeFund(fund.schemeCode)} className="text-muted-foreground hover:text-red-500">
                                        <X className="w-4 h-4" />
                                    </button>
                                </div>
                            ))}
                        </div>
                    )}

                    {/* Params Row 1 */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        <div className="space-y-2">
                            <label className="text-xs font-semibold text-muted-foreground uppercase">Installment Amount</label>
                            <div className="relative">
                                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">₹</span>
                                <Input type="number" value={amount} onChange={e => setAmount(Number(e.target.value))} className="pl-7" />
                            </div>
                        </div>
                        <div className="space-y-2">
                            <label className="text-xs font-semibold text-muted-foreground uppercase">Frequency</label>
                            <Select value={frequency} onValueChange={setFrequency}>
                                <SelectTrigger><SelectValue /></SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="Monthly">Monthly</SelectItem>
                                    <SelectItem value="Quarterly">Quarterly</SelectItem>
                                </SelectContent>
                            </Select>
                        </div>
                        <div className="flex items-end pb-2 gap-2">
                            <div className="flex items-center space-x-2 border p-2 rounded-md bg-muted/10 w-full h-10">
                                <Checkbox id="stepUp" checked={isStepUp} onCheckedChange={(c) => setIsStepUp(!!c)} />
                                <label htmlFor="stepUp" className="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70">
                                    Yearly Step-Up?
                                </label>
                            </div>
                        </div>
                    </div>

                    {/* Params Row 2 - Dates & StepUp */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        <div className="space-y-2">
                            <label className="text-xs font-semibold text-muted-foreground uppercase">Start Date</label>
                            <Input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} />
                        </div>
                        <div className="space-y-2">
                            <label className="text-xs font-semibold text-muted-foreground uppercase">End Date</label>
                            <Input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} />
                        </div>

                        {isStepUp && (
                            <div className="space-y-2 animate-in fade-in">
                                <label className="text-xs font-semibold text-blue-600 uppercase">Step-Up %</label>
                                <div className="relative">
                                    <Input type="number" value={stepUpPercent} onChange={e => setStepUpPercent(Number(e.target.value))} className="border-blue-200 focus:border-blue-500" />
                                    <span className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground">%</span>
                                </div>
                            </div>
                        )}

                        {!isStepUp && <div className="hidden md:block"></div>}
                    </div>

                    <Button onClick={calculate} disabled={loading || selectedFunds.length === 0} className="w-full md:w-auto bg-emerald-600 hover:bg-emerald-700 text-white font-bold">
                        {loading ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Calculator className="w-4 h-4 mr-2" />}
                        Calculate Returns
                    </Button>

                </CardContent>
            </Card>

            {/* Results Section */}
            {result && (
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    {/* Summary Table */}
                    <Card className="lg:col-span-3 border-border/50 shadow-sm overflow-hidden">
                        <div className="px-6 py-4 border-b border-border/50 bg-muted/10">
                            <h3 className="font-semibold text-foreground">Summary Snapshot</h3>
                        </div>
                        <div className="overflow-x-auto">
                            <table className="w-full text-sm text-left">
                                <thead className="bg-muted/30 text-muted-foreground font-medium border-b border-border/50">
                                <tr>
                                    <th className="px-6 py-4">Fund Name</th>
                                    <th className="px-6 py-4 text-right">Total Invested</th>
                                    <th className="px-6 py-4 text-right">Current Value</th>
                                    <th className="px-6 py-4 text-right">Profit</th>
                                    {/* <th className="px-6 py-4 text-right">XIRR</th> */}
                                </tr>
                                </thead>
                                <tbody className="divide-y divide-border/40">
                                {result.results.map((row) => (
                                    <tr key={row.schemeCode} className="hover:bg-muted/10">
                                        <td className="px-6 py-4 font-medium">{row.schemeName}</td>
                                        <td className="px-6 py-4 text-right text-muted-foreground">
                                            {new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(Number(row.totalInvested))}
                                        </td>
                                        <td className="px-6 py-4 text-right font-bold text-foreground">
                                            {new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(Number(row.currentValue))}
                                        </td>
                                        <td className={`px-6 py-4 text-right font-bold ${Number(row.absoluteReturn) >= 0 ? 'text-emerald-600' : 'text-red-500'}`}>
                                            {new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(Number(row.absoluteReturn))}
                                        </td>
                                        {/* <td className="px-6 py-4 text-right font-mono">{row.xirr}%</td> */}
                                    </tr>
                                ))}
                                </tbody>
                            </table>
                        </div>
                    </Card>

                    {/* Comparison Chart */}
                    <Card className="lg:col-span-3 border-border/50 shadow-sm">
                        <CardHeader>
                            <CardTitle className="text-sm font-medium uppercase tracking-wide">Growth Comparison</CardTitle>
                        </CardHeader>
                        <CardContent className="h-[400px]">
                            <ResponsiveContainer width="100%" height="100%">
                                <LineChart data={chartData} margin={{ top: 10, right: 30, left: 10, bottom: 0 }}>
                                    <CartesianGrid strokeDasharray="3 3" vertical={false} opacity={0.1} />
                                    <XAxis
                                        dataKey="date"
                                        tickFormatter={(val) => new Date(val).getFullYear().toString()}
                                        minTickGap={50}
                                        tick={{fontSize: 12, fill: '#888'}}
                                    />
                                    <YAxis
                                        tickFormatter={(val) => `₹${val/1000}k`}
                                        tick={{fontSize: 12, fill: '#888'}}
                                        width={60}
                                    />
                                    <Tooltip
                                        labelFormatter={(val) => new Date(val).toLocaleDateString()}
                                        formatter={(val: number) => new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(val)}
                                        contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }}
                                    />
                                    <Legend />

                                    {/* Invested Line (Grey Dashed) */}
                                    <Line type="monotone" dataKey="invested" name="Total Invested" stroke="#94a3b8" strokeDasharray="5 5" strokeWidth={2} dot={false} />

                                    {/* Dynamic Lines for Each Fund */}
                                    {result.results.map((res, i) => (
                                        <Line
                                            key={res.schemeCode}
                                            type="monotone"
                                            dataKey={`fund_${res.schemeCode}`}
                                            name={res.schemeName}
                                            stroke={COLORS[i % COLORS.length]}
                                            strokeWidth={3}
                                            dot={false}
                                        />
                                    ))}
                                </LineChart>
                            </ResponsiveContainer>
                        </CardContent>
                    </Card>
                </div>
            )}
        </div>
    );
}

"use client";

import React, { useEffect, useState } from 'react';
import {
    ArrowRightLeft, TrendingUp, Search, Calendar, Check, ArrowDownCircle, ArrowUpCircle
} from 'lucide-react';
import {
    Card, CardContent, CardHeader, CardTitle, CardDescription
} from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import {
    Select, SelectContent, SelectItem, SelectTrigger, SelectValue
} from '@/components/ui/select';
import {
    Popover, PopoverContent, PopoverTrigger,
} from "@/components/ui/popover";
import {
    Command, CommandInput, CommandEmpty, CommandGroup, CommandItem,
} from "@/components/ui/command";
import {
    AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend
} from 'recharts';
import { researchService, StpResponse, SchemeDropdownDto } from '@/services/researchService';
import { cn } from "@/lib/utils";
import { Loader2 } from 'lucide-react';

export default function StpCalculatorView() {
    // Data Loading State
    const [categories, setCategories] = useState<string[]>([]);
    const [loading, setLoading] = useState(false);
    const [result, setResult] = useState<StpResponse | null>(null);

    // Form State
    const [initialAmount, setInitialAmount] = useState(1000000);
    const [transferAmount, setTransferAmount] = useState(25000);
    const [frequency, setFrequency] = useState("Monthly");
    const [investDate, setInvestDate] = useState("2022-01-01");
    const [stpDate, setStpDate] = useState("2022-02-01");
    const [endDate, setEndDate] = useState(new Date().toISOString().split('T')[0]);

    // Source Fund Selector
    const [sourceCat, setSourceCat] = useState("Debt: Liquid");
    const [sourceFund, setSourceFund] = useState<SchemeDropdownDto | null>(null);

    // Target Fund Selector
    const [targetCat, setTargetCat] = useState("Equity: Large Cap");
    const [targetFund, setTargetFund] = useState<SchemeDropdownDto | null>(null);

    // Initial Load
    useEffect(() => {
        researchService.getCategories().then(setCategories);
    }, []);

    const calculate = async () => {
        if (!sourceFund || !targetFund) return;
        setLoading(true);
        try {
            const res = await researchService.calculateStp({
                initialInvestmentAmount: initialAmount,
                transferAmount,
                sourceSchemeCode: sourceFund.schemeCode,
                targetSchemeCode: targetFund.schemeCode,
                startDate: investDate,
                stpStartDate: stpDate,
                endDate,
                frequency
            });
            setResult(res);
        } catch (err) {
            console.error(err);
        } finally {
            setLoading(false);
        }
    };

    const fmt = (val: number) => new Intl.NumberFormat('en-IN', {
        style: 'currency', currency: 'INR', maximumFractionDigits: 0
    }).format(val);

    return (
        <div className="space-y-8 animate-in fade-in duration-700 pb-20">
            {/* Header */}
            <div>
                <h1 className="text-2xl font-bold tracking-tight flex items-center gap-2">
                    <ArrowRightLeft className="w-6 h-6 text-emerald-500" />
                    STP Calculator
                </h1>
                <p className="text-sm text-muted-foreground mt-1">
                    Systematic Transfer Plan: Simulate transferring wealth from Debt to Equity.
                </p>
            </div>

            {/* Config Card */}
            <Card className="border-border/50 shadow-md">
                <CardHeader className="bg-muted/10 pb-4 border-b border-border/50">
                    <CardTitle className="text-base text-blue-600">Transfer Configuration</CardTitle>
                </CardHeader>
                <CardContent className="p-6 space-y-8">

                    {/* Fund Selection Row */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8 relative">
                        {/* Source Box */}
                        <div className="space-y-4 p-4 border border-orange-200 bg-orange-50/50 dark:bg-orange-950/10 rounded-xl relative">
                            <Badge className="absolute -top-3 left-4 bg-orange-500 hover:bg-orange-600 shadow-sm">Source (From)</Badge>
                            <div className="space-y-2">
                                <label className="text-xs font-semibold text-muted-foreground">Category</label>
                                <Select value={sourceCat} onValueChange={setSourceCat}>
                                    <SelectTrigger className="bg-background w-full h-9 text-xs"><span className="truncate text-left block w-full pr-2"><SelectValue /></span></SelectTrigger>
                                    <SelectContent>{categories.map(c => <SelectItem key={c} value={c}>{c}</SelectItem>)}</SelectContent>
                                </Select>
                            </div>
                            <div className="space-y-2">
                                <label className="text-xs font-semibold text-muted-foreground">Fund</label>
                                <FundCombobox category={sourceCat} selected={sourceFund} onSelect={setSourceFund} placeholder="Select Liquid Fund..." />
                            </div>
                            <div className="space-y-2">
                                <label className="text-xs font-semibold text-muted-foreground">Lumpsum Investment</label>
                                <div className="relative">
                                    <span className="absolute left-3 top-2.5 text-muted-foreground">₹</span>
                                    <Input type="number" value={initialAmount} onChange={e => setInitialAmount(Number(e.target.value))} className="pl-7 bg-background h-9" />
                                </div>
                            </div>
                        </div>

                        {/* Arrow Icon */}
                        <div className="hidden md:flex absolute inset-0 items-center justify-center pointer-events-none">
                            <div className="bg-background p-2 rounded-full border shadow-sm z-10">
                                <ArrowRightLeft className="w-5 h-5 text-muted-foreground" />
                            </div>
                        </div>

                        {/* Target Box */}
                        <div className="space-y-4 p-4 border border-emerald-200 bg-emerald-50/50 dark:bg-emerald-950/10 rounded-xl relative">
                            <Badge className="absolute -top-3 left-4 bg-emerald-600 hover:bg-emerald-700 shadow-sm">Target (To)</Badge>
                            <div className="space-y-2">
                                <label className="text-xs font-semibold text-muted-foreground">Category</label>
                                <Select value={targetCat} onValueChange={setTargetCat}>
                                    <SelectTrigger className="bg-background w-full h-9 text-xs"><span className="truncate text-left block w-full pr-2"><SelectValue /></span></SelectTrigger>
                                    <SelectContent>{categories.map(c => <SelectItem key={c} value={c}>{c}</SelectItem>)}</SelectContent>
                                </Select>
                            </div>
                            <div className="space-y-2">
                                <label className="text-xs font-semibold text-muted-foreground">Fund</label>
                                <FundCombobox category={targetCat} selected={targetFund} onSelect={setTargetFund} placeholder="Select Equity Fund..." />
                            </div>
                            <div className="space-y-2">
                                <label className="text-xs font-semibold text-muted-foreground">Transfer Amount (STP)</label>
                                <div className="relative">
                                    <span className="absolute left-3 top-2.5 text-muted-foreground">₹</span>
                                    <Input type="number" value={transferAmount} onChange={e => setTransferAmount(Number(e.target.value))} className="pl-7 bg-background h-9" />
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Timeline Row */}
                    <div className="grid grid-cols-1 md:grid-cols-4 gap-6 pt-2">
                        <div className="space-y-1.5">
                            <label className="text-xs font-semibold text-muted-foreground">Initial Invest Date</label>
                            <Input type="date" value={investDate} onChange={e => setInvestDate(e.target.value)} className="h-9" />
                        </div>
                        <div className="space-y-1.5">
                            <label className="text-xs font-semibold text-muted-foreground">STP Start Date</label>
                            <Input type="date" value={stpDate} onChange={e => setStpDate(e.target.value)} className="h-9" />
                        </div>
                        <div className="space-y-1.5">
                            <label className="text-xs font-semibold text-muted-foreground">End Date</label>
                            <Input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="h-9" />
                        </div>
                        <div className="flex items-end">
                            <Button onClick={calculate} disabled={loading || !sourceFund || !targetFund} className="w-full h-9 bg-blue-600 hover:bg-blue-700 text-white font-bold shadow-sm">
                                {loading ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : "Run Simulation"}
                            </Button>
                        </div>
                    </div>
                </CardContent>
            </Card>

            {result && (
                <div className="space-y-8">

                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                        <SummaryCard label="Total Invested" value={result.totalValue - result.totalProfit} subLabel="Initial Capital" />
                        <SummaryCard label="Transferred Amount" value={result.totalTransferred} subLabel="Moved to Target" color="text-blue-600" />
                        <SummaryCard label="Current Value" value={result.totalValue} subLabel="Combined Portfolio" color="text-emerald-600" bold />
                        <SummaryCard label="Net Profit" value={result.totalProfit} subLabel={`${((result.totalProfit / initialAmount) * 100).toFixed(2)}% Return`} color={result.totalProfit >= 0 ? "text-emerald-600" : "text-red-500"} />
                    </div>

                    <Card className="border-border/50 shadow-sm">
                        <CardHeader className="py-4 border-b border-border/50 bg-muted/10">
                            <CardTitle className="text-sm font-medium uppercase tracking-wide">Portfolio Value Over Time</CardTitle>
                        </CardHeader>
                        <CardContent className="h-[350px] pt-6 pr-6">
                            <ResponsiveContainer width="100%" height="100%">
                                <AreaChart data={result.ledger} margin={{ top: 10, right: 0, left: 20, bottom: 0 }}>
                                    <defs>
                                        <linearGradient id="colorTarget" x1="0" y1="0" x2="0" y2="1">
                                            <stop offset="5%" stopColor="#10b981" stopOpacity={0.3}/>
                                            <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                                        </linearGradient>
                                        <linearGradient id="colorSource" x1="0" y1="0" x2="0" y2="1">
                                            <stop offset="5%" stopColor="#f97316" stopOpacity={0.3}/>
                                            <stop offset="95%" stopColor="#f97316" stopOpacity={0}/>
                                        </linearGradient>
                                    </defs>
                                    <XAxis dataKey="date" tickFormatter={(val) => new Date(val).getFullYear().toString()} minTickGap={50} tick={{fontSize: 12, fill: '#888'}} />
                                    <YAxis tickFormatter={(val) => `₹${val/1000}k`} tick={{fontSize: 12, fill: '#888'}} />
                                    <Tooltip
                                        labelFormatter={(v) => new Date(v).toLocaleDateString()}
                                        formatter={(val: number) => fmt(val)}
                                        contentStyle={{borderRadius: '8px', border:'1px solid #e2e8f0'}}
                                    />
                                    <Legend />
                                    <Area type="monotone" dataKey="targetMarketValue" name="Target Fund (Equity)" stackId="1" stroke="#10b981" fill="url(#colorTarget)" />
                                    <Area type="monotone" dataKey="sourceMarketValue" name="Source Fund (Debt)" stackId="1" stroke="#f97316" fill="url(#colorSource)" />
                                </AreaChart>
                            </ResponsiveContainer>
                        </CardContent>
                    </Card>

                    <Card className="border-border/50 shadow-sm overflow-hidden">
                        <div className="px-6 py-4 border-b border-border/50 bg-muted/10 flex justify-between items-center">
                            <h3 className="font-bold text-foreground flex items-center gap-2">
                                <Search className="w-4 h-4 text-muted-foreground" />
                                Transaction Ledger
                            </h3>
                            <Badge variant="outline" className="font-mono text-xs">
                                {result.ledger.length} Transactions
                            </Badge>
                        </div>
                        <div className="overflow-x-auto max-h-[500px]">
                            <table className="w-full text-sm text-left relative">
                                <thead className="bg-muted/50 text-muted-foreground font-medium text-xs uppercase sticky top-0 z-10 backdrop-blur-md">
                                <tr>
                                    <th className="px-4 py-3 min-w-[100px]">Date</th>
                                    <th className="px-4 py-3 text-center border-l border-border/50 bg-orange-50/50 dark:bg-orange-900/10 text-orange-700 dark:text-orange-400">
                                        Source Fund (Sell)
                                    </th>
                                    <th className="px-4 py-3 text-center border-l border-border/50 bg-emerald-50/50 dark:bg-emerald-900/10 text-emerald-700 dark:text-emerald-400">
                                        Target Fund (Buy)
                                    </th>
                                    <th className="px-4 py-3 text-right border-l border-border/50">Total Value</th>
                                </tr>
                                </thead>
                                <tbody className="divide-y divide-border/40">
                                {result.ledger.map((row, idx) => (
                                    <tr key={idx} className="hover:bg-muted/10 transition-colors">
                                        <td className="px-4 py-3 font-medium whitespace-nowrap text-muted-foreground">
                                            {new Date(row.date).toLocaleDateString()}
                                            <div className="text-[10px] uppercase mt-0.5 opacity-60">{row.type.replace('_', ' ')}</div>
                                        </td>
                                        <td className="px-4 py-3 border-l border-border/50">
                                            <div className="flex justify-between text-xs mb-1">
                                                <span className="text-muted-foreground">
                                                    {/* SAFE CHECK: Handle potential nulls in NAV */}
                                                    NAV: {row.sourceNav ? row.sourceNav.toFixed(2) : '-'}
                                                </span>
                                                <span className="text-orange-600 font-mono">
                                                    {row.unitsSold && row.unitsSold > 0 ? `-${row.unitsSold.toFixed(2)} Units` : '-'}
                                                </span>
                                            </div>
                                            <div className="text-right font-mono text-xs font-medium text-orange-700 dark:text-orange-400">
                                                {fmt(row.sourceMarketValue)}
                                            </div>
                                        </td>
                                        <td className="px-4 py-3 border-l border-border/50">
                                            <div className="flex justify-between text-xs mb-1">
                                                <span className="text-muted-foreground">
                                                    {/* FIX: Ensure targetNav is not null before toFixed() */}
                                                    NAV: {row.targetNav ? row.targetNav.toFixed(2) : '-'}
                                                </span>
                                                <span className="text-emerald-600 font-mono">
                                                    {row.unitsBought && row.unitsBought > 0 ? `+${row.unitsBought.toFixed(2)} Units` : '-'}
                                                </span>
                                            </div>
                                            <div className="text-right font-mono text-xs font-medium text-emerald-700 dark:text-emerald-400">
                                                {fmt(row.targetMarketValue)}
                                            </div>
                                        </td>

                                        {/* Total */}
                                        <td className="px-4 py-3 text-right border-l border-border/50 font-mono font-bold text-foreground">
                                            {fmt(row.totalPortfolioValue)}
                                        </td>
                                    </tr>
                                ))}
                                </tbody>
                            </table>
                        </div>
                    </Card>
                </div>
            )}
        </div>
    );
}

// --- Helper Components ---

function SummaryCard({ label, value, subLabel, color = "text-foreground", bold }: any) {
    const fmt = (val: number) => new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(val);
    return (
        <Card className="bg-card border-border/50 shadow-sm">
            <CardContent className="p-4">
                <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider mb-1">{label}</p>
                <p className={`text-lg ${bold ? 'font-black' : 'font-bold'} ${color} tracking-tight`}>{fmt(value)}</p>
                {subLabel && <p className="text-[10px] text-muted-foreground mt-1">{subLabel}</p>}
            </CardContent>
        </Card>
    );
}

function FundCombobox({ category, selected, onSelect, placeholder }: any) {
    const [open, setOpen] = useState(false);
    const [list, setList] = useState<SchemeDropdownDto[]>([]);

    useEffect(() => {
        if(open && category) {
            researchService.getSchemesByCategory(category).then(setList);
        }
    }, [open, category]);

    return (
        <Popover open={open} onOpenChange={setOpen}>
            <PopoverTrigger asChild>
                <Button variant="outline" role="combobox" className="w-full justify-between bg-background font-normal text-muted-foreground h-9 px-3 text-xs border-input/60 shadow-sm">
                    <span className="truncate text-left block w-full pr-2">{selected ? selected.schemeName : placeholder}</span>
                    <Search className="ml-2 h-3 w-3 shrink-0 opacity-50" />
                </Button>
            </PopoverTrigger>
            <PopoverContent className="w-[var(--radix-popover-trigger-width)] min-w-[280px] p-0" align="start">
                <Command>
                    <CommandInput placeholder="Search fund..." className="h-8 text-xs" />
                    <CommandEmpty>No fund found.</CommandEmpty>
                    <CommandGroup className="max-h-[200px] overflow-auto">
                        {list.map((s) => (
                            <CommandItem
                                key={s.schemeCode}
                                value={s.schemeName}
                                onSelect={() => {
                                    onSelect(s);
                                    setOpen(false);
                                }}
                                className="text-xs py-1.5"
                            >
                                <Check className={cn("mr-2 h-3 w-3", selected?.schemeCode === s.schemeCode ? "opacity-100" : "opacity-0")} />
                                <span className="truncate">{s.schemeName}</span>
                            </CommandItem>
                        ))}
                    </CommandGroup>
                </Command>
            </PopoverContent>
        </Popover>
    );
}

"use client";

import React, { useEffect, useState } from 'react';
import {
    ArrowDownCircle, Wallet, Search, Calendar, Check, TrendingDown
} from 'lucide-react';
import {
    Card, CardContent, CardHeader, CardTitle
} from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from "@/components/ui/input";
import {
    Select, SelectContent, SelectItem, SelectTrigger, SelectValue
} from '@/components/ui/select';
import {
    Popover, PopoverContent, PopoverTrigger,
} from "@/components/ui/popover";
import {
    Command, CommandInput, CommandEmpty, CommandGroup, CommandItem,
} from "@/components/ui/command";
import {
    AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend
} from 'recharts';
import { researchService, SwpResponse, SchemeDropdownDto } from '@/services/researchService';
import { cn } from "@/lib/utils";
import { Loader2 } from 'lucide-react';
import { ErrorAlert } from '@/components/ui/ErrorAlert';

export default function SwpCalculatorView() {
    // Data State
    const [categories, setCategories] = useState<string[]>([]);
    const [category, setCategory] = useState("");
    const [schemes, setSchemes] = useState<SchemeDropdownDto[]>([]);

    // Form State
    const [selectedScheme, setSelectedScheme] = useState<SchemeDropdownDto | null>(null);
    const [lumpsum, setLumpsum] = useState(1000000);
    const [withdrawal, setWithdrawal] = useState(6000); // Rule of thumb: 6-8% annual
    const [investDate, setInvestDate] = useState("2018-01-01");
    const [swpStartDate, setSwpStartDate] = useState("2018-02-01");
    const [swpEndDate, setSwpEndDate] = useState(new Date().toISOString().split('T')[0]);
    const [frequency, setFrequency] = useState("Monthly");

    // Result State
    const [result, setResult] = useState<SwpResponse | null>(null);
    const [loading, setLoading] = useState(false);
    const [comboOpen, setComboOpen] = useState(false);
    const [error, setError] = useState<string | null>(null);

    // Initial Load
    useEffect(() => {
        researchService.getCategories().then(cats => {
            setCategories(cats);
            const hybridCat = cats.find(c => c.includes("Hybrid") || c.includes("Balanced"));
            if(hybridCat) setCategory(hybridCat);
            else if(cats.length) setCategory(cats[0]);
        });
    }, []);

    // Load Schemes
    useEffect(() => {
        if (!category) return;
        researchService.getSchemesByCategory(category).then(setSchemes);
    }, [category]);

    const calculate = async () => {
        if (!selectedScheme) return;
        setLoading(true);
        try {
            const res = await researchService.calculateSwp({
                schemeCode: selectedScheme.schemeCode,
                initialInvestmentAmount: lumpsum,
                investmentDate: investDate,
                withdrawalAmount: withdrawal,
                swpStartDate,
                swpEndDate,
                frequency
            });
            setResult(res);
        } catch (err) {
            console.error(err);
            const msg = err.response?.data?.message || "An unexpected error occurred. Please verify dates and try again.";
            setError(msg);
        } finally {
            setLoading(false);
        }
    };

    const fmt = (val: number) => new Intl.NumberFormat('en-IN', {
        style: 'currency', currency: 'INR', maximumFractionDigits: 0
    }).format(val);

    return (
        <div className="space-y-8 animate-in fade-in duration-700 pb-20">
            {/* Header */}
            <div>
                <h1 className="text-2xl font-bold tracking-tight flex items-center gap-2">
                    <ArrowDownCircle className="w-6 h-6 text-emerald-500" />
                    SWP Calculator
                </h1>
                <p className="text-sm text-muted-foreground mt-1">
                    Generate regular income from your investments while keeping capital invested.
                </p>
            </div>

            {/* Input Card */}
            <Card className="border-border/50 shadow-md">
                <CardHeader className="bg-muted/10 pb-4 border-b border-border/50">
                    <CardTitle className="text-base text-blue-600">Withdrawal Configuration</CardTitle>
                </CardHeader>
                <CardContent className="p-6 space-y-6">

                    {/* Fund Selection */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div className="space-y-2">
                            <label className="text-xs font-semibold text-muted-foreground uppercase">Category</label>
                            <Select value={category} onValueChange={setCategory}>
                                <SelectTrigger className="bg-background h-10 w-full">
                                    <span className="truncate text-left block w-full pr-2"><SelectValue /></span>
                                </SelectTrigger>
                                <SelectContent>{categories.map(c => <SelectItem key={c} value={c}>{c}</SelectItem>)}</SelectContent>
                            </Select>
                        </div>
                        <div className="space-y-2">
                            <label className="text-xs font-semibold text-muted-foreground uppercase">Select Scheme</label>
                            <Popover open={comboOpen} onOpenChange={setComboOpen}>
                                <PopoverTrigger asChild>
                                    <Button variant="outline" role="combobox" className="w-full justify-between bg-background font-normal text-muted-foreground h-10 px-3">
                                        <span className="truncate">{selectedScheme ? selectedScheme.schemeName : "Select Fund..."}</span>
                                        <Search className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                                    </Button>
                                </PopoverTrigger>
                                <PopoverContent className="w-[var(--radix-popover-trigger-width)] min-w-[300px] p-0" align="start">
                                    <Command>
                                        <CommandInput placeholder="Search fund..." />
                                        <CommandEmpty>No fund found.</CommandEmpty>
                                        <CommandGroup className="max-h-[250px] overflow-auto">
                                            {schemes.map((s) => (
                                                <CommandItem
                                                    key={s.schemeCode}
                                                    value={s.schemeName}
                                                    onSelect={() => {
                                                        setSelectedScheme(s);
                                                        setComboOpen(false);
                                                    }}
                                                >
                                                    <Check className={cn("mr-2 h-4 w-4", selectedScheme?.schemeCode === s.schemeCode ? "opacity-100" : "opacity-0")} />
                                                    <span className="truncate">{s.schemeName}</span>
                                                </CommandItem>
                                            ))}
                                        </CommandGroup>
                                    </Command>
                                </PopoverContent>
                            </Popover>
                        </div>
                    </div>

                    {/* Amounts */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        <div className="space-y-2">
                            <label className="text-xs font-semibold text-muted-foreground uppercase">Initial Lumpsum</label>
                            <div className="relative">
                                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">₹</span>
                                <Input type="number" value={lumpsum} onChange={e => setLumpsum(Number(e.target.value))} className="pl-7 h-10" />
                            </div>
                        </div>
                        <div className="space-y-2">
                            <label className="text-xs font-semibold text-muted-foreground uppercase">Monthly Withdrawal</label>
                            <div className="relative">
                                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">₹</span>
                                <Input type="number" value={withdrawal} onChange={e => setWithdrawal(Number(e.target.value))} className="pl-7 h-10" />
                            </div>
                        </div>
                        <div className="space-y-2">
                            <label className="text-xs font-semibold text-muted-foreground uppercase">Frequency</label>
                            <Select value={frequency} onValueChange={setFrequency}>
                                <SelectTrigger className="h-10"><SelectValue /></SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="Monthly">Monthly</SelectItem>
                                    <SelectItem value="Quarterly">Quarterly</SelectItem>
                                </SelectContent>
                            </Select>
                        </div>
                    </div>

                    {/* Dates */}
                    <div className="grid grid-cols-1 md:grid-cols-4 gap-6 pt-2">
                        <div className="space-y-2">
                            <label className="text-xs font-semibold text-muted-foreground uppercase">Investment Date</label>
                            <Input type="date" value={investDate} onChange={e => setInvestDate(e.target.value)} className="h-10" />
                        </div>
                        <div className="space-y-2">
                            <label className="text-xs font-semibold text-muted-foreground uppercase">SWP Start Date</label>
                            <Input type="date" value={swpStartDate} onChange={e => setSwpStartDate(e.target.value)} className="h-10" />
                        </div>
                        <div className="space-y-2">
                            <label className="text-xs font-semibold text-muted-foreground uppercase">End Date</label>
                            <Input type="date" value={swpEndDate} onChange={e => setSwpEndDate(e.target.value)} className="h-10" />
                        </div>
                        <div className="flex items-end">
                            <Button onClick={calculate} disabled={loading || !selectedScheme} className="w-full h-10 bg-emerald-600 hover:bg-emerald-700 text-white font-bold shadow-sm">
                                {loading ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : "Calculate SWP"}
                            </Button>
                        </div>
                    </div>
                </CardContent>
            </Card>

            <ErrorAlert message={error} />
            {/* Results */}
            {result && (
                <div className="space-y-8">
                    {/* Summary Cards */}
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                        <SummaryCard label="Total Invested" value={lumpsum} subLabel="One-time" />
                        <SummaryCard label="Total Withdrawn" value={result.totalWithdrawn} subLabel="Cash back to you" color="text-emerald-600" />
                        <SummaryCard label="Current Value" value={result.finalValue} subLabel="Remaining in Fund" color="text-blue-600" bold />
                        <SummaryCard label="Net Profit" value={result.totalProfit} subLabel="(Withdrawn + Current) - Invested" color={result.totalProfit >= 0 ? "text-emerald-600" : "text-red-500"} />
                    </div>

                    {/* Chart */}
                    <Card className="border-border/50 shadow-sm">
                        <CardHeader className="py-4 border-b border-border/50 bg-muted/10">
                            <CardTitle className="text-sm font-medium uppercase tracking-wide">Fund Value vs Withdrawal</CardTitle>
                        </CardHeader>
                        <CardContent className="h-[350px] pt-6 pr-6">
                            <ResponsiveContainer width="100%" height="100%">
                                <AreaChart data={result.ledger} margin={{ top: 10, right: 0, left: 20, bottom: 0 }}>
                                    <defs>
                                        <linearGradient id="colorValue" x1="0" y1="0" x2="0" y2="1">
                                            <stop offset="5%" stopColor="#2563eb" stopOpacity={0.3}/>
                                            <stop offset="95%" stopColor="#2563eb" stopOpacity={0}/>
                                        </linearGradient>
                                    </defs>
                                    <XAxis dataKey="date" tickFormatter={(val) => new Date(val).getFullYear().toString()} minTickGap={50} tick={{fontSize: 12, fill: '#888'}} />
                                    <YAxis tickFormatter={(val) => `₹${val/1000}k`} tick={{fontSize: 12, fill: '#888'}} />
                                    <Tooltip labelFormatter={(v) => new Date(v).toLocaleDateString()} formatter={(val: number) => fmt(val)} contentStyle={{borderRadius:'8px'}}/>
                                    <Legend />
                                    <Area type="monotone" dataKey="currentValue" name="Fund Value" stroke="#2563eb" fill="url(#colorValue)" strokeWidth={2} />
                                    {/* Optional: Add Invested Line */}
                                    <Area type="monotone" dataKey={() => lumpsum} name="Initial Capital" stroke="#94a3b8" fill="none" strokeDasharray="5 5" />
                                </AreaChart>
                            </ResponsiveContainer>
                        </CardContent>
                    </Card>

                    {/* Ledger Table */}
                    <Card className="border-border/50 shadow-sm overflow-hidden">
                        <div className="px-6 py-4 border-b border-border/50 bg-muted/10">
                            <h3 className="font-bold text-foreground">Withdrawal Schedule</h3>
                        </div>
                        <div className="overflow-x-auto max-h-[500px]">
                            <table className="w-full text-sm text-left relative">
                                <thead className="bg-muted/50 text-muted-foreground font-medium text-xs uppercase sticky top-0 z-10 backdrop-blur-md">
                                <tr>
                                    <th className="px-6 py-3">Date</th>
                                    <th className="px-6 py-3 text-right">NAV</th>
                                    <th className="px-6 py-3 text-right text-emerald-600">Cash Flow</th>
                                    <th className="px-6 py-3 text-right">Units Balance</th>
                                    <th className="px-6 py-3 text-right">Fund Value</th>
                                </tr>
                                </thead>
                                <tbody className="divide-y divide-border/40">
                                {result.ledger.map((row, idx) => (
                                    <tr key={idx} className="hover:bg-muted/10 transition-colors">
                                        <td className="px-6 py-3 font-medium whitespace-nowrap">{new Date(row.date).toLocaleDateString()}</td>
                                        <td className="px-6 py-3 text-right text-muted-foreground">{row.nav.toFixed(4)}</td>
                                        <td className={`px-6 py-3 text-right font-mono font-medium ${row.cashFlow > 0 ? 'text-emerald-600' : 'text-slate-500'}`}>
                                            {row.cashFlow > 0 ? '+' : ''}{fmt(row.cashFlow)}
                                        </td>
                                        <td className="px-6 py-3 text-right text-muted-foreground">{row.balanceUnits.toFixed(3)}</td>
                                        <td className="px-6 py-3 text-right font-bold text-foreground">{fmt(row.currentValue)}</td>
                                    </tr>
                                ))}
                                </tbody>
                            </table>
                        </div>
                    </Card>
                </div>
            )}
        </div>
    );
}

function SummaryCard({ label, value, subLabel, color = "text-foreground", bold }: any) {
    const fmt = (val: number) => new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(val);
    return (
        <Card className="bg-card border-border/50 shadow-sm">
            <CardContent className="p-4">
                <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider mb-1">{label}</p>
                <p className={`text-lg ${bold ? 'font-black' : 'font-bold'} ${color} tracking-tight`}>{fmt(value)}</p>
                {subLabel && <p className="text-[10px] text-muted-foreground mt-1">{subLabel}</p>}
            </CardContent>
        </Card>
    );
}

"use client";

import React, { useEffect, useState } from 'react';
import {
    Calendar, TrendingUp, DollarSign, Filter, Search, ArrowRight, Loader2, Coins
} from 'lucide-react';
import {
    Card, CardContent, CardHeader, CardTitle, CardDescription
} from '@/components/ui/card';
import {
    Select, SelectContent, SelectItem, SelectTrigger, SelectValue
} from '@/components/ui/select';
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Slider } from "@/components/ui/slider";
import { Badge } from "@/components/ui/badge";
import {
    BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, ReferenceLine
} from 'recharts';
import { researchService, LumpsumRequest, LumpsumResponse } from '@/services/researchService';
import { ErrorAlert } from '@/components/ui/ErrorAlert';

// Preset Amounts for "Better UI" approach
const PRESET_AMOUNTS = [
    { label: '₹10k', value: 10000 },
    { label: '₹50k', value: 50000 },
    { label: '₹1L', value: 100000 },
    { label: '₹5L', value: 500000 },
    { label: '₹10L', value: 1000000 },
];

export default function TopLumpsumView() {
    // --- State ---
    const [categories, setCategories] = useState<string[]>([]);
    const [loading, setLoading] = useState(false);

    // Request State
    const [category, setCategory] = useState<string>("");
    const [amount, setAmount] = useState<number>(100000);
    const [years, setYears] = useState<number>(5);
    const [page, setPage] = useState(0);

    // Data State
    const [data, setData] = useState<LumpsumResponse | null>(null);
    const [error, setError] = useState<string | null>(null);

    // 1. Initial Load
    useEffect(() => {
        researchService.getCategories().then(cats => {
            setCategories(cats);
            if (cats.length > 0) setCategory(cats.includes("Equity") ? "Equity" : cats[0]);
        });
    }, []);

    // 2. Fetch Data
    useEffect(() => {
        if (!category) return;

        const fetch = async () => {
            setLoading(true);
            try {
                const res = await researchService.getTopLumpsumFunds({
                    category,
                    years,
                    amount,
                    page,
                    size: 20
                });
                setData(res);
            } catch (err) {
                console.error(err);
                const msg = err.response?.data?.message || "An unexpected error occurred. Please verify dates and try again.";
                setError(msg);
            } finally {
                setLoading(false);
            }
        };

        // Debounce slightly to prevent rapid firing on slider change
        const timer = setTimeout(fetch, 300);
        return () => clearTimeout(timer);
    }, [category, years, amount, page]);

    // Format Currency Helper
    const fmt = (val: number) => new Intl.NumberFormat('en-IN', {
        style: 'currency', currency: 'INR', maximumFractionDigits: 0
    }).format(val);

    return (
        <div className="space-y-6 animate-in fade-in duration-700 pb-20">
            {/* --- Header --- */}
            <div>
                <h1 className="text-2xl md:text-3xl font-bold tracking-tight text-foreground flex items-center gap-2">
                    <Coins className="w-8 h-8 text-emerald-500" />
                    Top Performing Lumpsum Funds
                </h1>
                <p className="text-sm text-muted-foreground mt-1">
                    Simulate past one-time investments to find wealth creators.
                </p>
            </div>

            {/* --- Controls Section (Advanced & Better UI) --- */}
            {/* --- Controls Section --- */}
            <Card className="border-border/50 bg-card/50 backdrop-blur-sm sticky top-4 z-20 shadow-md">
                <CardContent className="p-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-12 gap-6 items-start">

                        {/* 1. Category Selector */}
                        <div className="lg:col-span-4 space-y-2 w-full min-w-0">
                            {/* min-w-0 is crucial for flex/grid children to truncate correctly */}
                            <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">
                                Category
                            </label>
                            <Select value={category} onValueChange={(v) => { setCategory(v); setPage(0); }}>
                                <SelectTrigger className="h-10 bg-background w-full">
                                    {/* The span + truncate ensures text doesn't overflow on mobile */}
                                    <span className="truncate text-left block w-full pr-2">
                                        <SelectValue placeholder="Select Category" />
                                    </span>
                                </SelectTrigger>
                                <SelectContent>
                                    {categories.map(c => <SelectItem key={c} value={c}>{c}</SelectItem>)}
                                </SelectContent>
                            </Select>
                        </div>

                        {/* 2. Amount Input with Quick Chips */}
                        <div className="lg:col-span-4 space-y-3 w-full">
                            <div className="flex justify-between items-center">
                                <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">
                                    Investment
                                </label>
                                <span className="text-xs text-emerald-600 font-mono font-bold bg-emerald-50 dark:bg-emerald-900/30 px-2 py-0.5 rounded">
                                    {fmt(amount)}
                                </span>
                            </div>

                            <div className="relative">
                                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground font-medium">₹</span>
                                <Input
                                    type="number"
                                    value={amount}
                                    onChange={(e) => setAmount(Number(e.target.value))}
                                    className="pl-7 h-10 bg-background border-input/80 focus:border-emerald-500 transition-colors"
                                />
                            </div>

                            <div className="flex gap-2 flex-wrap">
                                {PRESET_AMOUNTS.map(preset => (
                                    <button
                                        key={preset.value}
                                        onClick={() => setAmount(preset.value)}
                                        className={`text-[10px] font-medium px-2.5 py-1 rounded-md border transition-all
                                            ${amount === preset.value
                                            ? 'bg-emerald-600 text-white border-emerald-600 shadow-sm'
                                            : 'bg-background text-muted-foreground border-border hover:border-emerald-400 hover:text-emerald-600'}`}
                                    >
                                        {preset.label}
                                    </button>
                                ))}
                            </div>
                        </div>

                        {/* 3. Time Period Slider */}
                        <div className="md:col-span-2 lg:col-span-4 space-y-4 w-full pt-1">
                            <div className="flex justify-between items-center">
                                <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Time Period</label>
                                <Badge variant="outline" className="font-mono text-emerald-600 bg-emerald-50 dark:bg-emerald-950/20 h-6">
                                    {years} Years
                                </Badge>
                            </div>
                            <div className="px-1 py-2">
                                <Slider
                                    value={[years]}
                                    onValueChange={(val) => setYears(val[0])}
                                    min={1} max={25} step={1}
                                    className="cursor-pointer"
                                />
                            </div>
                            <div className="flex justify-between text-[10px] text-muted-foreground px-1 font-medium">
                                <span>1Y</span>
                                <span>5Y</span>
                                <span>10Y</span>
                                <span>15Y</span>
                                <span>20Y</span>
                                <span>25Y</span>
                            </div>
                        </div>

                    </div>
                </CardContent>
            </Card>

            <ErrorAlert message={error} />
            {/* --- Visuals & Data --- */}
            {loading ? (
                <div className="h-64 flex flex-col items-center justify-center gap-4 text-muted-foreground">
                    <Loader2 className="w-10 h-10 animate-spin text-emerald-500" />
                    <p>Simulating {years} years of growth...</p>
                </div>
            ) : !data?.funds.length ? (
                <div className="h-64 flex items-center justify-center text-muted-foreground border-2 border-dashed rounded-xl">
                    No funds found for this criteria. Try changing the category or years.
                </div>
            ) : (
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

                    {/* Top 5 Growth Chart */}
                    <Card className="lg:col-span-3 border-border/50 shadow-sm">
                        <CardHeader className="pb-2">
                            <CardTitle className="text-sm font-medium uppercase tracking-wide">Top 5 Wealth Creators (Current Value)</CardTitle>
                        </CardHeader>
                        <CardContent className="h-[250px]">
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={data.funds.slice(0, 5)} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
                                    <CartesianGrid strokeDasharray="3 3" vertical={false} opacity={0.2} />
                                    <XAxis dataKey="schemeName" tick={{fontSize: 10}} interval={0} tickFormatter={(val) => val.length > 15 ? val.substring(0, 15) + '...' : val} />
                                    <YAxis tickFormatter={(val) => `₹${val/1000}k`} fontSize={11} />
                                    <Tooltip
                                        cursor={{fill: 'transparent'}}
                                        content={({ active, payload, label }) => {
                                            if (active && payload && payload.length) {
                                                return (
                                                    <div className="bg-popover border border-border p-3 rounded shadow-lg text-xs">
                                                        <p className="font-bold mb-1">{label}</p>
                                                        <p>Invested: {fmt(payload[0].payload.investedAmount)}</p>
                                                        <p className="text-emerald-600 font-bold text-sm mt-1">
                                                            Current: {fmt(payload[0].value as number)}
                                                        </p>
                                                        <p className="text-muted-foreground mt-1">CAGR: {payload[0].payload.cagr}%</p>
                                                    </div>
                                                );
                                            }
                                            return null;
                                        }}
                                    />
                                    <ReferenceLine y={amount} stroke="#f59e0b" strokeDasharray="3 3" label={{ value: 'Invested', position: 'insideTopLeft', fill: '#f59e0b', fontSize: 10 }} />
                                    <Bar dataKey="currentValue" fill="url(#colorGradient)" radius={[4, 4, 0, 0]} maxBarSize={60}>
                                        {data.funds.slice(0, 5).map((entry, index) => (
                                            <Cell key={`cell-${index}`} fill={index === 0 ? '#10b981' : '#34d399'} />
                                        ))}
                                    </Bar>
                                </BarChart>
                            </ResponsiveContainer>
                        </CardContent>
                    </Card>

                    {/* Data Table */}
                    <Card className="lg:col-span-3 border-border/50 shadow-sm overflow-hidden bg-card">
                        <div className="px-6 py-4 border-b border-border/50 bg-muted/10 flex justify-between items-center">
                            <div>
                                <h3 className="font-semibold text-foreground">Detailed Performance</h3>
                                <p className="text-xs text-muted-foreground">Data as of {data.dataAsOn}</p>
                            </div>
                            <Badge variant="outline" className="bg-background">
                                {data.totalElements} Funds
                            </Badge>
                        </div>
                        <div className="overflow-x-auto">
                            <table className="w-full text-sm text-left">
                                <thead className="bg-muted/30 text-muted-foreground font-medium border-b border-border/50">
                                <tr>
                                    <th className="px-6 py-3 w-[50px]">#</th>
                                    <th className="px-6 py-3">Scheme Name</th>
                                    <th className="px-4 py-3 text-right">CAGR</th>
                                    <th className="px-4 py-3 text-right">Profit</th>
                                    <th className="px-4 py-3 text-right">Current Value</th>
                                </tr>
                                </thead>
                                <tbody className="divide-y divide-border/40">
                                {data.funds.map((fund, index) => (
                                    <tr key={fund.schemeCode} className="hover:bg-muted/30 transition-colors group">
                                        <td className="px-6 py-3 text-muted-foreground font-mono text-xs">{(page * 20) + index + 1}</td>
                                        <td className="px-6 py-3">
                                            <div className="font-medium text-foreground group-hover:text-emerald-600 transition-colors">
                                                {fund.schemeName}
                                            </div>
                                            <div className="text-[10px] text-muted-foreground flex gap-2 mt-0.5">
                                                <span>NAV Start: ₹{fund.startNav?.toFixed(2)}</span>
                                                <span>•</span>
                                                <span>NAV End: ₹{fund.currentNav?.toFixed(2)}</span>
                                            </div>
                                        </td>
                                        <td className="px-4 py-3 text-right font-mono text-emerald-600 dark:text-emerald-400 font-medium">
                                            {fund.cagr}%
                                        </td>
                                        <td className="px-4 py-3 text-right">
                                            <span className="text-emerald-600 text-xs font-bold">+</span>
                                            {fmt(fund.absoluteReturn)}
                                        </td>
                                        <td className="px-4 py-3 text-right font-bold text-foreground">
                                            {fmt(fund.currentValue)}
                                        </td>
                                    </tr>
                                ))}
                                </tbody>
                            </table>
                        </div>

                        {/* Pagination */}
                        <div className="flex items-center justify-between px-6 py-4 border-t border-border/50 bg-muted/5">
                            <Button
                                variant="outline" size="sm"
                                disabled={page === 0}
                                onClick={() => setPage(p => p - 1)}
                            >
                                Previous
                            </Button>
                            <span className="text-xs text-muted-foreground">Page {page + 1} of {data.totalPages}</span>
                            <Button
                                variant="outline" size="sm"
                                disabled={page >= data.totalPages - 1}
                                onClick={() => setPage(p => p + 1)}
                            >
                                Next
                            </Button>
                        </div>
                    </Card>
                </div>
            )}
        </div>
    );
}

"use client";

import React, { useEffect, useState } from 'react';
import {
    ChevronLeft, ChevronRight, ArrowUpDown, ArrowUp, ArrowDown,
    Calendar, Info, Loader2
} from 'lucide-react';
import {
    Card, CardContent, CardHeader, CardTitle
} from '@/components/ui/card';
import {
    Select, SelectContent, SelectItem, SelectTrigger, SelectValue
} from '@/components/ui/select';
import {
    Tooltip, TooltipContent, TooltipProvider, TooltipTrigger,
} from "@/components/ui/tooltip";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { researchService, TopFundsRequest, TopFundsResponse } from '@/services/researchService';
import { ErrorAlert } from '@/components/ui/ErrorAlert';

export default function TopPerformingFundsView() {
    const [categories, setCategories] = useState<string[]>([]);
    const [loading, setLoading] = useState(false);

    // Query State
    const [request, setRequest] = useState<TopFundsRequest>({
        category: '',
        page: 0,
        size: 15,
        sortBy: 'return_3y',
        sortDirection: 'DESC'
    });

    const [data, setData] = useState<TopFundsResponse | null>(null);
    const [error, setError] = useState<string | null>(null);

    // 1. Load Categories
    useEffect(() => {
        researchService.getCategories().then(cats => {
            setCategories(cats);
            if (cats.length > 0) {
                // Default to Equity if available, else first category
                const defaultCat = cats.includes('Equity') ? 'Equity' : cats[0];
                setRequest(prev => ({ ...prev, category: defaultCat }));
            }
        });
    }, []);

    // 2. Fetch Data
    useEffect(() => {
        if (!request.category) return;
        const fetchData = async () => {
            setLoading(true);
            try {
                const res = await researchService.getTopPerformingFunds(request);
                setData(res);
            } catch (err) {
                console.error("Failed to fetch top funds", err);
                const msg = err.response?.data?.message || "An unexpected error occurred. Please verify dates and try again.";
                setError(msg);
            } finally {
                setLoading(false);
            }
        };
        fetchData();
    }, [request]);

    const handleSort = (field: string) => {
        setRequest(prev => ({
            ...prev,
            sortBy: field as any,
            sortDirection: prev.sortBy === field && prev.sortDirection === 'DESC' ? 'ASC' : 'DESC'
        }));
    };

    // Helper for coloring returns
    const ReturnCell = ({ value }: { value: number | null }) => {
        if (value === null || value === undefined) return <span className="text-muted-foreground">-</span>;
        const color = value >= 20 ? 'text-emerald-600 dark:text-emerald-400 font-bold' :
            value >= 10 ? 'text-emerald-600/80 dark:text-emerald-400/80' :
                value < 0 ? 'text-red-500' : 'text-foreground';
        return <span className={`font-mono ${color}`}>{value.toFixed(2)}%</span>;
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-700 pb-10">
            {/* --- Header --- */}
            <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
                <div>
                    <h1 className="text-2xl md:text-3xl font-bold tracking-tight text-foreground flex items-center gap-2">
                        Top Performing Funds
                        <TooltipProvider>
                            <Tooltip>
                                <TooltipTrigger>
                                    <Info className="w-4 h-4 text-muted-foreground hover:text-foreground transition-colors" />
                                </TooltipTrigger>
                                <TooltipContent>
                                    <p>Based on annualized returns (CAGR).</p>
                                </TooltipContent>
                            </Tooltip>
                        </TooltipProvider>
                    </h1>
                    <p className="text-sm text-muted-foreground mt-1 flex items-center gap-2">
                        <Calendar className="w-3 h-3" />
                        Data as on {data?.dataAsOn || '...'}
                    </p>
                </div>

                {/* Added min-w-0 to prevent flex overflow issues */}
                <div className="w-full md:w-[280px] min-w-0 space-y-1.5">
                    <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider ml-1">Category</label>
                    <Select
                        value={request.category}
                        onValueChange={(v) => setRequest(prev => ({ ...prev, category: v, page: 0 }))}
                    >
                        <SelectTrigger className="h-10 bg-card border-input/60 shadow-sm w-full">
                            {/* TRUNCATION FIX: Wraps text to prevent layout breaking on mobile */}
                            <span className="truncate text-left block w-full pr-2">
                        <SelectValue placeholder="Select Category" />
                    </span>
                        </SelectTrigger>
                        <SelectContent>
                            {categories.map(c => <SelectItem key={c} value={c}>{c}</SelectItem>)}
                        </SelectContent>
                    </Select>
                </div>
            </div>

            <ErrorAlert message={error} />
            {/* --- Comparison Cards --- */}
            {data && (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {/* Category Avg Card */}
                    <Card className="bg-gradient-to-br from-blue-50/50 to-background dark:from-blue-950/10 dark:to-card border-blue-100 dark:border-blue-900/30">
                        <CardHeader className="pb-2">
                            <CardTitle className="text-xs font-bold text-blue-600 dark:text-blue-400 uppercase tracking-widest">
                                Category Average ({request.category})
                            </CardTitle>
                        </CardHeader>
                        <CardContent>
                            <div className="flex justify-between items-end pt-2">
                                <StatBox label="1 Year" value={data.categoryAverage.return1y} />
                                <StatBox label="3 Year" value={data.categoryAverage.return3y} border />
                                <StatBox label="5 Year" value={data.categoryAverage.return5y} border />
                            </div>
                        </CardContent>
                    </Card>

                    {/* Benchmark Card */}
                    <Card className="bg-gradient-to-br from-slate-50/50 to-background dark:from-slate-900/10 dark:to-card border-slate-100 dark:border-slate-800">
                        <CardHeader className="pb-2 flex flex-row items-center justify-between space-y-0">
                            <CardTitle className="text-xs font-bold text-slate-600 dark:text-slate-400 uppercase tracking-widest">
                                Benchmark
                            </CardTitle>
                            {data.benchmark && <Badge variant="secondary" className="text-[10px] h-5">{data.benchmark.name}</Badge>}
                        </CardHeader>
                        <CardContent>
                            {data.benchmark ? (
                                <div className="flex justify-between items-end pt-2">
                                    <StatBox label="1 Year" value={data.benchmark.return1y} />
                                    <StatBox label="3 Year" value={data.benchmark.return3y} border />
                                    <StatBox label="5 Year" value={data.benchmark.return5y} border />
                                </div>
                            ) : (
                                <div className="flex items-center justify-center h-[52px] text-sm text-muted-foreground italic">
                                    Benchmark data not available
                                </div>
                            )}
                        </CardContent>
                    </Card>
                </div>
            )}

            {/* --- Main Data Table --- */}
            <Card className="border-border/50 shadow-sm overflow-hidden bg-card">
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left">
                        <thead className="bg-muted/50 text-muted-foreground font-medium border-b border-border/50">
                        <tr>
                            <th className="px-6 py-4 w-[35%] min-w-[250px]">Scheme Name</th>
                            <SortHeader label="1Y" field="return_1y" req={request} onClick={handleSort} />
                            <SortHeader label="3Y" field="return_3y" req={request} onClick={handleSort} />
                            <SortHeader label="5Y" field="return_5y" req={request} onClick={handleSort} />
                            <SortHeader label="Inception" field="return_inception" req={request} onClick={handleSort} />
                            <th className="px-6 py-4 text-center">Vol. (StdDev)</th>
                        </tr>
                        </thead>
                        <tbody className="divide-y divide-border/40">
                        {loading ? (
                            <tr>
                                <td colSpan={6} className="h-40 text-center">
                                    <div className="flex flex-col items-center justify-center text-muted-foreground gap-2">
                                        <Loader2 className="w-6 h-6 animate-spin text-emerald-500" />
                                        <span>Analyzing Funds...</span>
                                    </div>
                                </td>
                            </tr>
                        ) : !data?.funds.length ? (
                            <tr>
                                <td colSpan={6} className="h-32 text-center text-muted-foreground">No funds found in this category.</td>
                            </tr>
                        ) : (
                            data.funds.map((fund) => (
                                <tr key={fund.schemeCode} className="hover:bg-muted/30 transition-colors group">
                                    <td className="px-6 py-4">
                                        <div className="font-semibold text-foreground group-hover:text-emerald-600 transition-colors cursor-pointer">
                                            {fund.schemeName}
                                        </div>
                                        <div className="text-xs text-muted-foreground mt-0.5">Code: {fund.schemeCode}</div>
                                    </td>
                                    <td className="px-6 py-4 text-right"><ReturnCell value={fund.return1y} /></td>
                                    <td className="px-6 py-4 text-right bg-muted/20 font-medium"><ReturnCell value={fund.return3y} /></td>
                                    <td className="px-6 py-4 text-right"><ReturnCell value={fund.return5y} /></td>
                                    <td className="px-6 py-4 text-right"><ReturnCell value={fund.returnInception} /></td>
                                    <td className="px-6 py-4 text-center text-muted-foreground">
                                        {fund.stdDev ? fund.stdDev.toFixed(2) : '-'}
                                    </td>
                                </tr>
                            ))
                        )}
                        </tbody>
                    </table>
                </div>

                {/* --- Pagination Footer --- */}
                {data && (
                    <div className="flex items-center justify-between px-6 py-4 border-t border-border/50 bg-muted/10">
                        <div className="text-xs text-muted-foreground">
                            Showing {Math.min((request.page * request.size) + 1, data.totalElements)} - {Math.min((request.page + 1) * request.size, data.totalElements)} of {data.totalElements}
                        </div>
                        <div className="flex items-center gap-2">
                            <Button
                                variant="outline" size="sm"
                                disabled={request.page === 0}
                                onClick={() => setRequest(p => ({...p, page: p.page - 1}))}
                            >
                                <ChevronLeft className="w-4 h-4" />
                            </Button>
                            <span className="text-xs font-medium px-2">Page {request.page + 1} of {data.totalPages}</span>
                            <Button
                                variant="outline" size="sm"
                                disabled={request.page >= data.totalPages - 1}
                                onClick={() => setRequest(p => ({...p, page: p.page + 1}))}
                            >
                                <ChevronRight className="w-4 h-4" />
                            </Button>
                        </div>
                    </div>
                )}
            </Card>
        </div>
    );
}

// Sub-components for cleaner code
function StatBox({ label, value, border }: { label: string, value: number | undefined, border?: boolean }) {
    return (
        <div className={`text-center flex-1 ${border ? 'border-l border-border' : ''}`}>
            <p className="text-[10px] uppercase text-muted-foreground mb-1">{label}</p>
            <p className="text-lg font-bold tracking-tight">
                {value ? `${value.toFixed(2)}%` : '-'}
            </p>
        </div>
    );
}

function SortHeader({ label, field, req, onClick }: any) {
    const isActive = req.sortBy === field;
    return (
        <th
            className="px-6 py-4 text-right cursor-pointer hover:text-emerald-500 transition-colors select-none group"
            onClick={() => onClick(field)}
        >
            <div className="flex items-center justify-end gap-1">
                {label}
                <div className={`flex flex-col ${isActive ? 'text-emerald-500' : 'text-muted-foreground/30'}`}>
                    {isActive && req.sortDirection === 'ASC' ? <ArrowUp className="w-3 h-3" /> :
                        isActive && req.sortDirection === 'DESC' ? <ArrowDown className="w-3 h-3" /> :
                            <ArrowUpDown className="w-3 h-3" />}
                </div>
            </div>
        </th>
    );
}

