} from 'lucide-react';
import { researchService, TrailingReturnsResponse, SchemeDropdownDto } from '@/services/researchService';

import { cn } from "@/lib/utils";

import {
    Popover,
    PopoverTrigger,
    PopoverContent,
} from "@/components/ui/popover";

import {
